window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26434719"]={"book":{"id":26434719,"title":"你一年的8760小时","author":"艾力","translator":"","publisher":"江苏凤凰文艺出版社","pubdate":"2015-8","isbn":"9787539984476","tags":["时间管理","励志","艾力","个人管理","个人成长","好书","值得一读","我想读这本书","成长"],"memCount":10},"np":1,"pb":[12],"idx":[{"i":16696,"t":"“利用好下班前的10分钟，为你的人生增值”","l":"TF2-1","c":"晨捷","g":1,"p":1},{"i":16030,"t":"不要在为拖延症内疚了","l":"TF2-1","c":"沈丹萍","g":1,"p":1},{"i":6542,"t":"时间管理主题","l":"TF2-1","c":"鸳鸯","g":0,"p":1},{"i":4104,"t":"利用好下班前的10分钟，为你的人生增值","l":"TF2-2","c":"吴印梅","g":1,"p":1},{"i":3994,"t":"如何制定一个可实现的短小目标","l":"TF2-1","c":"吴印梅","g":1,"p":1},{"i":2923,"t":"找到自己人生的目标","l":"TF2-4","c":"John","g":1,"p":1},{"i":2207,"t":"人生的目标","l":"TF2-4","c":"John","g":1,"p":1},{"i":2091,"t":"34枚硬币时间记录法","l":"TF1-1","c":"羽美人","g":1,"p":1},{"i":1000,"t":"寻找自己的人生目标","l":"TF3-3","c":"莫妮卡","g":1,"p":1},{"i":835,"t":"逆向时间规划法","l":"TF3-2","c":"莫妮卡","g":1,"p":1},{"i":775,"t":"通过记录时间，了解自己，制定诱人的生活计划","l":"TF2-4","c":"莫妮卡","g":1,"p":1},{"i":571,"t":"甲之熊掌，乙之砒霜。","l":"TF1-1","c":"陈庆","g":1,"p":1}],"ms":[{"id":16696,"topic":"“利用好下班前的10分钟，为你的人生增值”","learn_goal":"","remark":"用好下班前10分钟，获得高效工作、轻松休息和尽情娱乐","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"晨捷","city":"太原市"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"\u003cp>【自我介绍+学习目标】1分钟\u003c/p>\u003cp>过渡语：各位老师好！感谢伴随我进入今天的学习，此时为了TF2-1的学习内容而迭代了新的标签：赵~璞~，新鲜出苗的一级拆书家、职场老手、复盘工作坊讲师。\u003c/p>\u003cp>我们即将开始的学习主题是“利用好下班前的10分钟，为你的人生增值”，在跟随我完成本次RIA现场学习后，学习者能够重视各自下班前的10分钟，同时运用片段给出的6项建议每日复盘，实现日清日结。\u003c/p>\u003cp>（本次课程的学习目标没看到。用固定句式来明确下学习目标。）\u003c/p>\u003cp>【分组】30秒\u003c/p>\u003cp>今天到场的一共X位老师，我按照名单顺序，将单数为一组、双数为一组，学习过程中会有组内发言和分享学习的互动环节，还请大家积极参与，每次参与都是一次非常好的学习。\u003c/p>\u003cp>【图书介绍】2分钟\u003c/p>\u003cp>F-特征Feature：本书有汉语和维语两个版本，是俞敏洪倾情推荐，作者艾力是一位年轻的演说家和培训师，他总是在思考一个问题——生命是什么？结论便是[时间]！当以[小时]为单位、通过8760个小时的形式来本书命名，足以引发我们对时间的思考和重视。\u003c/p>\u003cp>A-优势Advantage：本书与其他书籍时间管理理念相比侧重于形象生动，以【34枚金币】比拟着每一份时间的价值；同时原理简单、使用灵活，带领我们把每天要做的事情分为5类，用不同的色块标记，一目了然；因此获得了公众号、小红书和B站的书籍推荐。\u003c/p>\u003cp>B-利益Benefit：\u003c/p>\u003cp>B1建议年轻人必读，因为年轻有可能对时间的概念不深，本书能帮助学习者识别常见的时间管理误区、战胜拖延症。\u003c/p>\u003cp>（这个利益点不够明确，查一下这本书解决什么问题等）\u003c/p>\u003cp>B2 本次拆页从下班前10分钟的视角，完成6项建议的内容，教会学习者如何把时间用到极致，实现高效工作、轻松休息和尽情娱乐。\u003c/p>","ratings_count":1,"texts":[{"id":20814,"quote":"\u003cp>【R阅读拆页】1分钟《利用好下班前的十分钟》\u003c/p>\u003cp>我们发现在办公室中，许多人快到下班的时候就心不在焉了。其实，下班前的10分钟是“黄金时间”，用好了可以起到“承前启后”的作用。如果你之前的下班前10分钟总是无所事事，从现在起不妨试试下面的几条建议：\u003c/p>\u003cp>1、整理备忘录\u003c/p>\u003cp>备忘录上记载了一天的工作摘要，包括当天会见的人士,新获得的名片资料等。内容多半繁杂无章，故在一天工作结束前将它整理一下。这样不但能掌握当天的工作进展,也便于日后翻阅。\u003c/p>\u003cp>2、检查工作表\u003c/p>\u003cp>当天应进行的工作项目，已完成的做上记号，对未完成的项目也做到心中有数。\u003c/p>\u003cp>3、检查邮箱\u003c/p>\u003cp>在下班前的十分钟，你可以检查一下自己的邮箱,看看有没有接收到新的邮件，有没有什么重要邮件被错过了，很多企业里,一些管理者因为上班时间很忙，他们会在下班前的时间内给他人回邮件，所以如果你的领导有什么重要的事交代给你的话，也许会发到你的邮箱。\u003c/p>\u003cp>4、拟订次日的工作表\u003c/p>\u003cp>把当天的工作表检查完毕后，接着列出次日应进行的工作项目，拟订工作表。此时可参照备忘录，以防疏漏。\u003c/p>\u003cp>5、反思工作\u003c/p>\u003cp>很多人在一段时间工作以后绩效没有提高，但往往找不到原因。其实，你可以利用下班前的十分钟时间反思自己，有时每天一点小失误就可能在无形中导致大失误，而自己却未曾发现。采取每天反思自己的方式，能够让职场人牢记自己每天的具体工作细节，方便以后的工作总结。\u003c/p>\u003cp>6、整理办公桌\u003c/p>\u003cp>下班前将办公桌整理得干干净净，才算真正结束一天的工作。你需要整理的有：别人递上来的新名片、新做的报表，别人给你的重要文件等。是否都放在了合适的地方，那些需要锁好的物品，是不是放进了抽屉？另外，你还可以主动把办公室的垃圾倒出去，清洗自己的茶杯等，这样不至于在下班前没有事做，而且第二天看见整齐的办公桌也会心情大好。\u003c/p>\u003cp>在工作中我们听到很多人抱怨时间不够，其实是浪费的时间太多能充分利用的却很少。人生的每一分钟都值得好好利用，下班前的十分钟看上去不起眼，但如果我们能充分利用起来，一定能在日积月累的工作中发挥重要的作用。\u003c/p>","explains":"\u003cp>【I便签】2分钟\u003c/p>\u003cp>【过渡语】大家在读片段的过程中，有没有在脑海中出现了自己下班前10分钟的画面呢？\u003c/p>\u003cp>接下来我将用3W1H四要素来谈谈我的理解，也请大家跟随我的指引一起参与其中，相信能共同受益。\u003c/p>\u003cp>1、What：知识点和相关理论阐述\u003c/p>\u003cp>我这次选取的是一个详细讲述时间管理[方法]的拆页，片段内容是讲在下班前10分钟里实施“1拟定、2整理、3检查”的6个小内容，帮助大家顺利完成全天工作的收尾，衔接了次日工作计划，还包括了复盘自评，专注做好小事形成良好的工作习惯。\u003c/p>\u003cp>2、Why：前因后果说明\u003c/p>\u003cp>【为什么要这么做】\u003c/p>\u003cp>①从内心感受的角度：安心下班、享受自由时间，不为未完结、不确定的工作结果提心吊胆；\u003c/p>\u003cp>②从上下反馈的角度：今日事今日毕，不遗漏、能避免损失；\u003c/p>\u003cp>③从能量提升角度：干净利落的环境会增加快乐因子，同时也为下一个工作日带来舒适愉快。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>给大家模拟三个场景，来觉察下内心的感受：\u003c/p>\u003cp>①临下班没有做好工作交圈，下班走到晚高峰的高架上，收到信息回一趟公司——怒；\u003c/p>\u003cp>②白天工作忙，漏看工作群要18：00前上报集团数据核查表格，被领导打来电话质问和指责——哀；\u003c/p>\u003cp>③早上刚到办公室，发现昨天有聚餐下班没顾上收拾桌子，有个新到访的客户资料忘记放在哪里了——烦。\u003c/p>\u003cp>【举反例】\u003c/p>\u003cp>今年对我来说是个特殊的一年，从年初到现在区域的新项目都未能顺利推进，导致我们的工作出现了不可预测性，也会有不少的闲散时间，几乎在快下班的时候摸鱼刷短视频，6点钟一到带着兴奋的心情起身就走，然后在月底核对考勤时出现了“漏打卡”，纠结在编出一个理由硬着头皮找领导审批补签申请，还是接受旷工半天的工资扣款。\u003c/p>\u003cp>3、How：片段给出的方法是什么？\u003c/p>\u003cp>1拟定：拟订次日的工作表\u003c/p>\u003cp>职场上列明工作计划必不可少，以年、月、周为主节点，充分利用班前班后10分钟安排日工作。\u003c/p>\u003cp>2整理：整理备忘录和办公桌\u003c/p>\u003cp>工作即将结束，快速整理电脑文档、笔记、往来资料和办公室，已完成工作归档、持续进行的做好标记、重要资料存放；打扫办公室为第二天开工节省时间。\u003c/p>\u003cp>3检查：查计划、查邮箱、查自己\u003c/p>\u003cp>“凡事预则立，不预则废”，查阅今天的工作计划完成情况，检查邮箱和工作群是否有遗漏信息，复盘自己当日工作有无问题和待提升项，如果“有”，立即整改或重新拟定。\u003c/p>\u003cp>4、Where：这个片段的适用边界是什么？\u003c/p>\u003cp>黄金10分钟不仅是在职场上下班前，还能用在会议、培训、活动、客户会谈，甚至可以带领孩子一起养成好习惯，在睡前10分钟回想下作业是否全部完成、第二天的课本是否带齐全等等。\u003c/p>\u003cp>【添加正例】\u003c/p>\u003cp>学完这个方法后，我对工作做出了调整：\u003c/p>\u003cp>①定：坚持做工作计划，分配好第二天要面试的候选人、约谈的客户时间段，空余时间还能持续学习；\u003c/p>\u003cp>②理：归档简历、整理电脑文件夹、装订学习资料，拿视觉笔记为例已经装订了3本手稿；\u003c/p>\u003cp>③查：形成记忆反射，没有再出现“漏打卡”的情况。\u003c/p>","interaction":"\u003cp>【A1显像提问】2分钟\u003c/p>\u003cp>Q1：给大家30秒来思考，请回想一下我们在过去一周内，有没有着急下班，没收拾物品的情况，然后描述下下班的场景？然后用时1分钟在小组中分享一下，只分享场景即可……\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>[李万娟]今天发生的一件要检讨的事情，前几天发完预备表之后就应该开始做过级PPT，做了一下之后就去忙别的事情，但是脑海里以为已经做完；导致今天的时间特别匆忙，PPT的质量也会被打折。\u003c/p>\u003cp>[张鹏]我有个刚刚的经历，下周要出差但是公司的系统是需要提前将出差行程录入，周五下班忘记这个事，导致周六又去了趟单位补发。\u003c/p>\u003cp>【A1+反思加工】8分钟\u003c/p>\u003cp>Q2：大家的分享非常有情境和画面感，现在如果有机会回到当时的场景，用刚学到的“1拟定、2整理、3检查”方法，重新安排下，请用2分钟时间写下来，然后5分钟在小组内分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>[张鹏]\u003c/p>\u003cp>根据刚刚提供的出差这个场景，会做出3个步骤：1.拟定下周的出差计划和维护HR系统；2整理带齐自己所需的资料，尤其是宣传资源；3.检查要用到的U盘、笔记本、电脑和身份证。我把出差必备品归纳为“伸（身份证）手（手机）要（钥匙）钱”。\u003c/p>\u003cp>【结语】1分钟\u003c/p>\u003cp>相聚的时间是短暂的，我们及时结束今天的话题，也是对时间很好的把控，一寸光阴一寸金，希望今天的小知识点能让大家生命价值翻倍，感谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1695782275000,"updated_at":1696838730000,"ria":true},{"id":16030,"topic":"不要在为拖延症内疚了","learn_goal":"","remark":"拖延症又犯了？焦虑、担心、自责？试试这二个办法，你会明白：你并不等于你的工作，克服拖延，尽力就好。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"沈丹萍","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家好，我是沈丹萍，欢迎大家来参加我的2-1拆书。\u003c/p>\u003cp>\u003cstrong>自我介绍：\u003c/strong>\u003c/p>\u003cp>若用拆书帮的三个标签介绍我自已：\u003c/p>\u003cp>首先，我是一个去标签的杂学家。秉承着君子不器的思想自由学习，终身成长，上半年刚考完项目管理，下半年开始到2025年，希望能拯救我的英语，并重拾日语和韩语，希望2年后某次分享能用其中一种语言。\u003c/p>\u003cp>其次，我也一个跨专业的HR.理工科出身的我从传统HRM到全球HRBP,再到人才发展，已经在人力资源领域从业近15年。\u003c/p>\u003cp>最后一个标签，在路上的拆书家，打怪升级，继续努力。\u003c/p>\u003cp>\u003cbr>为了更好的带拆学习，讨论分享，我们可以先完成分组。\u003c/p>\u003cp>今天跟着我完成RIA现场学习后，大家能够尝试克服拖延症的两种方式，控制自己不因拖延而内疚，活出自己的精彩。\u003c/p>\u003cp> \u003cstrong>F:特征，核心是“书”，用于满足好奇心。\u003c/strong>\u003c/p>\u003cp>今天拆的这本书叫做《你一年的8760小时》，作者是艾力。他身上有很多标签：新疆人，180斤胖子逆袭成北大男神，曾就职于新东方，创办了酷艾英语，参加过《奇葩说》《超级演说家》等节目。在《你一年的8760小时》这本书里，艾力创造了34枚金币的时间管理方法，帮助数万人管理人生，重启梦想，这是一本很赞的书。你拥有的不是365天，而是8760个小时。每一个小时，你都在改变自己 ，每一个小时，你都在走向梦想。\u003c/p>\u003cp>\u003cstrong>A:优势，重点是“比较”，用于建立安全感\u003c/strong>\u003c/p>\u003cp>与其他的时间管理和励志类图书相比，本书最大的优点有两个，第一是浅显易懂；第二作者在大量阅读相关致用类图书和实践的基础，以“34枚金币时间管理法”为核心，探讨从努力到如何努力的思维转变，并具体介绍了设定人生目标、激发个人潜力、时间管理、困境突破、人际关系5个重要且行之有效的方法。俞敏洪倾情作序，蔡康永、陈鲁豫、黄磊、等多人也强烈推荐。\u003c/p>\u003cp>\u003cstrong>B:利益，强调的是“你（学习者）”用于引发兴趣\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1：指这本书给学习者带来的好处\u003c/strong>\u003c/p>\u003cp>如果你像我一样，身边缺少一本讲方法而不是道理的心灵鸡汤，身边缺少一本正能量的时间管理法则的书籍，我把这本书推荐给你，可能它不能改变你的人生，但是能让我们像艾力那样，在这样的好的思想和方法的塑造下，一点点靠近你的梦想!\u003c/p>\u003cp>\u003cstrong>B2：指接下来的这个片段给学习者带来的好处\u003c/strong>\u003c/p>\u003cp>今天所拆片段的学习将教会大家正确理解拖延症的原理，找到克服拖延症的方法，从自我对话的改变和做最坏的打算开始，让自己的生活、工作更有秩序，更加精彩。\u003c/p>","ratings_count":1,"texts":[{"id":20108,"quote":"\u003cp>原文拆页：\u003c/p>\u003cp>在我们不断长大的过程中，人开始变得不再纯粹，事也变得不再纯粹。这样一组等式出现了：\u003c/p>\u003cp>我们把某一件事等同于自己的能力，等同于自我的价值。这就导致我们不断给自己压力，把自己变得物质化、标签化。一个自己说：我一定要表现得特别好，成绩特别好，工作特别棒才行。另一个自己却说： \u003c/p>\u003cp>我可能做不到。两个自己开始打架，于是那个高高在上的你，总是瞧不起那个在下面并不完美的你。两个你分离得越开，拖延症就会越明显。 \u003c/p>\u003cp>知道了拖延症的原理，如何去克服呢？ \u003c/p>\u003cp>\u003cstrong>首先，我们要改变和自己对话的方式。\u003c/strong>你会发现大部分有拖延症的人，经常会说，我不得不去，我必须得怎样怎样，没时间享受生活，真的非常痛苦。这样的对话方式会让你心里的两个自我分离，一个说你赶紧去做什么，一个说我不想去做，最后变成了我必须去做。如何改变呢？从今天开始，每次你想说我必须去做的时候，把它改成我想去做，我选择去做什么。一个简单的语言的变化，就会让你心里的那个自己有更好的自主权。 \u003c/p>\u003cp>\u003cstrong>其次，我们可以一开始就做好最坏的打算，如果木板没办法像石桥一样牢固，就在它旁边建一个安全网，这样你从A楼走到B楼就不会特别害怕了，反正掉下去也不会特别惨。\u003c/strong>现实工作中，你可以尝试想象下 ：事情做不成最差的结果是什么。很多时候我们会不由自主地把后果不断放大，才导致心理压力特别大。有时我录制《酷艾英语》，会担心万一我讲不好怎么办，万一我胖了怎么办，我的这些观众是不是就不喜欢我了。但后来我想，就算我胖了一些，就算录得不怎么好，还是会有一些人喜欢我的。这样一想，我就会开心一些，就算没人支持，我自己和自己聊天也是好的。就算这次不是最佳状态，但起码我迈出了第一步。所以下次，你也可以试着问一下自己，这项工作就算做不好，那又怎样。 \u003c/p>\u003cp>你 不需要成功，只需要尝试就好了。如果所有人都想一蹴而就，一下就成功，那世界就不会如此多彩了。如果爱迪生想一次就把电灯泡的制作材料找到，他未必能真正成功。如果所有作家想的是，出版的处女作就达到世界名著水平，那也不会有浩如烟海的文学经典了。任何的进展都是在不断修正中发生的，任何成绩都是在不断尝试中得到的。 \u003c/p>\u003cp>一个人最大的痛苦来自未完成任务而产生的持续的焦虑，以及在最后一刻完成任务而觉得任务没做好的负罪感。 \u003c/p>\u003cp>你并不等于你的工作，克服拖延，尽力就好。\u003c/p>","explains":"\u003cp>\u003cstrong>【what】\u003c/strong>在当今社会，“拖延”对于很多人来说都并不陌生。所以这个片段很好理解。它解释了拖延症的基本原理，让我们改变和自己对话的方式，并且一开始就做好最坏的打算，降低我们的焦虑和负罪感，更好的克服拖延症，调整我们的生活状态。\u003c/p>\u003cp>\u003cstrong>【why-为什么要这么做，这么做有什么好处，不这么做有什么坏处】\u003c/strong>但现实情况中，我们是怎么做的呢？我们可能下周要交的东西，直到周末还没动笔，想着再过一个小时、再过半个小时，时间还来得及，就这样拖过了整个周末。一边拖延、一边焦虑，唾弃拖延的自己。\u003c/p>\u003cp>\u003cstrong>【坏处】\u003c/strong>“拖延”的人，容易陷入“因为心情不好而拖延，因为拖延而心情更不好”的死循环。那些越容易受到心情不好影响的人，就越有可能拖延。对于情绪低落、内疚或焦虑的人，光是改善情绪，就花费了他们大量的认知资源，更不要谈完成任务了。\u003c/p>\u003cp>就像有人说的那样：时间匆匆溜走了，只留下无法掌控时间、更无法掌控生活的自己。\u003c/p>\u003cp>\u003cstrong>【举例-反例】\u003c/strong>这让我想起了自己之前备考的一些事情。上半年我在备考项目管理考试，因为5月底要考试，除了日常周末看书，5月份最后二周我请了几天年假刷题复习。早上送完孩子之后，我开始准备看书了，拿起手机一看8点46分，准备拖一会儿凑个整点，9点开始吧，结果看看手机，看看电脑，一不小心就9点18了，那就9点半开始吧……然后实际上那上午我基本上近11点才开始的，因为再不开始就要午饭了。然后午饭也随便叫了个外卖。看着还有还有5,6套真题没有二刷，很多错题解析还没复习，心里一阵懊恼。感觉自己有点差劲，做好的计划似乎都没如期兑现。所以下午开始刷题效率是非常差的，基本都是没在及格线。\u003c/p>\u003cp>看着这个成绩，心里异常烦闷，冷静后，我出来倒了杯水，想起书中的这个拆页克服拖延症的办法重新准备起下面的计划工作：\u003c/p>\u003cp>\u003cstrong>【how具体做法】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>首先，改变和自己的对话，化被动心态为主动权掌控\u003c/strong>\u003c/p>\u003cp>我告诉自己：之所以休假来看书，我是想把这几套题刷完，并且完成错题解析，我愿意花时间来专注这些，所以我会去完成我预期计划。\u003c/p>\u003cp>\u003cstrong>其次,一开始做最坏的打算，先做起来。\u003c/strong>\u003c/p>\u003cp>就算我这些真题或错题没有刷，因此没有考上，那我大不了再花2500来补考，能用钱来解决的事都不是啥大事，而且这次我已经学到了敏捷项目的常规流程了，收获也不少。最坏已经是这样了，我可以先做起来。\u003c/p>\u003cp>\u003cstrong>【正面案例】\u003c/strong>\u003c/p>\u003cp>（\u003cstrong>改变和自己的对话，化被动心态为主动权掌控\u003c/strong>）所以，下午的时候，我对自己说：先休息了半小时，然后1:30半起来重新看错题刷题；我自己可以花这些时间来完成今天的任务。\u003c/p>\u003cp>\u003cstrong>（一开始做最坏的打算，先做起来。）\u003c/strong>刷完一半的题目后，我想：即使最终考试成绩不理想，但我该看的书该听的课我都全了，也问心无愧了，做了这样的最坏打算后，我就沉浸在做题中。\u003c/p>\u003cp>而实际上，后面刷题的感觉和节奏也一点一点上来了，最终刷完了所有的题目。\u003c/p>\u003cp>\u003cstrong>【why 好处】\u003c/strong>\u003c/p>\u003cp>大家会发现，本来对拖延症的懊恼对自己是不太好的经历，经过调整和准备，我不仅慢慢改变了拖延的状态，而且提高了复习效率，我相信以后再次面对这样的事情，不仅知道要怎么做，而且一定能有一个更好的态度和心境去应对。\u003c/p>\u003cp>\u003cstrong>【where适用边界】：\u003c/strong>\u003c/p>\u003cp>以上方法适合于日常拖延的场景，可以是工作上的”(deadline)截止日期是第一生产力”，也可以是学习中的”临时抱佛脚”，或者生活中的各种踩点或迟到的情景，当然，如果是涉及生命中重大决策或关键唯一实践，我们还是更加慎重决策，不仅仅是克服拖延症的问题的。而日常常见的习惯、行为拖延，因为我们提高幸福感，活出精彩人生，就不能因拖延而内疚，就可以借鉴应用以上克服拖延症的方法，终有一天我们终能完全如愿以偿。\u003c/p>","interaction":"\u003cp>那么下面就请大家回忆一下，最近一段时间，你在工作、生活、学习中有没有出现类似明明定在上午9点就要做但却一拖再拖，到下午1点还没做，心里很烦躁的这种拖延的情况，或者明日复明日，把今天的事情推到明天，明天的事情推到后天，不到最后一刻绝不开始工作，但真正最后一刻做的时候却百般后悔，情绪很不好。那是什么样的场景呢？请写下当时的具体情况？请大家小组内可以讨论下。2分钟后我们邀请一位伙伴来分享。\u003c/p>\u003cp> \u003cbr>学习者分享：关于这个拖延，我想到了我的3-1过级的计划，本来说上个月一定要过级的，但是忙忙忙就到月底，也很惭愧，就暗暗对自己说下个月我肯定要过级。然后这个月师父问我，什么时候开始啊，我看看好像这个月还有时间的，就说忙完我手头的这两天就开始。而事实上这个过级是要从去年9月份计划，11月份准备开始的，但到现在还没开始准备选书及预备表等，心里感觉真的不知道之前在干嘛，懊恼，惭愧……\u003c/p>\u003cp>好的，非常感谢这位伙伴的分享。\u003c/p>\u003cp> 再来回顾一下克服拖延症的二个方法。\u003c/p>\u003cp>第一、\u003cstrong>改变和自己的对话，化被动心态为主动权掌控。\u003c/strong>\u003c/p>\u003cp>第二、\u003cstrong>一开始做最坏的打算，先做起来。\u003c/strong>\u003c/p>\u003cp>如果大家重新回到我们刚才讨论到的那个情境，结合我们拆页方法，你会如何做呢？\u003c/p>\u003cp>请大家再花4分钟时间思考和讨论， 4分钟后我们邀请一位小伙伴来分享一下。\u003c/p>\u003cp>学习者分享：我来说下对于过级拖延这个事情，我尝试怎么克服。\u003c/p>\u003cp>首先我要改变和自己的方式，\u003cstrong>化被动心态为主动权掌控。\u003c/strong>要想着我愿意去做这件事，我选择去本月完成过级。因为是我自己要求的，选择的，相对可能工作学习优先级都提高，我要主动去做。\u003c/p>\u003cp>其次一开始做好最坏的打算，先做起来。我这个月准备了，大不了这次没有过级，那我也可以听听拆书家们的建议，我下次重新准备，继续过，一次不行二次，二次不行三次……我相信先做起来，终有一天肯定会过级的。\u003c/p>\u003cp>通过以上尝试，我相信每次过级都不会拖延了。\u003c/p>\u003cp>谢谢小伙伴精彩分享。\u003c/p>\u003cp>一个人最大的痛苦来自未完成任务而产生的持续的焦虑，以及在最后一刻完成任务而觉得任务没做好的负罪感。你并不等于你的工作，克服拖延，尽力就好。\u003c/p>\u003cp>好的，我今天的带拆就到这里，希望大家可以尝试今天提到的两个方法：改变和自己对话的方式来化被动心态为主动权掌控以及一开始就做好最坏的打算，先做起来，不因拖延而过多内疚，活出精彩人生。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1686623836000,"updated_at":1686639081000,"ria":true},{"id":6542,"topic":"时间管理主题","learn_goal":"学会使用“34枚金币时间管理法”记录一天的时间","remark":"我们经常会订很多计划，然而总是完不成。一天过去了，计划的事还没有做完。这是为什么呢？ 定计划就好比写药方，问题是，还没有把脉，我不知道我的病症在哪里，怎么可以乱吃药呢。时间管理也是一样的，如果我们不知道时间浪费在了哪里，谈何优化呢？\r\n\r\n所以，要解决这个问题，需要先记录你的时间，《你一年的8760小时》核心的34枚金币时间管理法，可以帮到你。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"鸳鸯","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是喜乐分舵的拆书家鸳鸯。\r\nF:\r\n今天拆的这本书叫做《你一年的8760小时》，是《超级演说家》 《奇葩说》最具正能量的“男神级演讲天才”艾力首部作品。得到俞敏洪、蔡康永、陈鲁豫、黄磊等大咖的极力推荐。\r\n这本书比较核心的“34枚金币时间管理法”，在2014年CCTV《经济生活大调查》被王小丫特别推介，影响上亿人次，帮助数万人管理人生，重启梦想。一本很赞的书。\r\nA：\r\n这本书和一般的时间管理书籍不同的是，它不仅是讲怎么管理时间的，他是以“34枚金币时间管理法”为核心，系统介绍了设定人生目标、激发个人潜力、时间管理、困境突破、人际关系5个重要领域行之有效的方法。全面系统，让你通过管理时间，实现管理人生。\r\nB：如果常常拖延，管理不好自己的时间，迷茫找不到目标，你都需要学习这本书，这本书可以告诉你如何战胜拖延，如何制定目标，如何管理好时间，如何突破困境，激发个人潜力，让自己的生活、工作更有秩序。","ratings_count":0,"texts":[{"id":9864,"quote":"\u003cp>用34枚金币时间管理法，时间就能像账单一样被记得很清楚。\u003c/p>\u003cp>原理很简单：早上7点起床，晚上12点睡觉，17个醒着的小时，按半小时划分，将时间分为34份，就有了34枚金币。\u003c/p>\u003cp>每天晚上，数一下金币是怎么花的，你就有了一个非常不错的收获，你会发现，一天的时间，都干了什么，高效与否，一目了然。这也是我这一年能做那么多事的最重要的原因。\u003c/p>\u003cp>有的人会问：为什么是7点起床，不能8点起床？可以，那就是32枚金币。9点起床可不可以？那就是30枚金币。\u003c/p>\u003cp>以半小时为单位来记录的原因是，半小时是我们大部分人完成一部分工作的时间，半小时足够了。或者说，你要完成4小时的工作，半小时是你做好准备进入这个工作的时间。半小时屁股坐稳了开始写论文，你就可以一直写下去，但如果这里动动，那里动动，刷刷微博，聊聊朋友圈，那我相信，你可能一直进入不了状态。\u003c/p>\u003cp>记录的时候，不必每过半小时就停下来去记录，我每天是睡觉前花5到10分钟去记。甚至有些时候，我两三天乃至一个星期都忘记了，还是会花半个小时时间坐在那里，认真回想并记录前几天的事情。如果晚上记录的时候，一天做过什么都想不起来了怎么办？那就果断标记成浪费的时间。如果你这段时间高效工作、认真学习了，你肯定不会忘记。如果这段时间你玩得非常开心，和同学聚会吃饭了，你也不会忘记。什么样的事会记不住？就是干那些没有意义的事情，刷微博、看网页。\u003c/p>","explains":"\u003cp>不那么做的坏处：（why）\u003c/p>\u003cp>大多数人是这样的，我今天干了啥？好像啥也没干啊！我这周干了啥？好像也没干啥！我这个月都干啥了，完全想不起来。为什么每个人一天都是24小时，有的人每天过得非常充实，工作、交友、健身、学习，什么都不耽误。而有的人一天感觉啥事也没做，眼一睁一闭，一天就没了，完全不知道时间都去哪儿了？如果你不记录自己的时间花费，那么你永远都不会知道你的时间都浪费在了哪里，又谈何优化呢？\u003c/p>\u003cp>今天的拆页我们来学习34枚金币时间管理法，像记账单一样记录我们的时间，找出被我们浪费掉的时间，从而去不断优化改进，让我们的工作更有效率，生活更丰富多彩，身心更健康快乐，人生变得更有价值。\u003c/p>\u003cp>知识点讲解：（what）\u003c/p>\u003cp>那么什么是34枚金币时间管理法呢？作者每天睡7个小时，于是他有17个小时来工作和生活，将这17个小时，按照半个小时为1枚金币计算，他一天就有了34枚金币。他管理这34枚金币的方法，就是他管理时间的方法。今天的拆页只是讲34枚金币管理的第一步——记录金币（时间）的用途。\u003c/p>\u003cp>为什么一定是34枚金币呢？34枚金币只是作者自己的标准，因为他一天清醒的时间是17个小时，你也可以有自己的标准，清醒16个小时，折合32枚金币，15个小时，折合30枚金币，以此类推。为什么半小时一枚金币？因为半小时是大部分人完成一部分工作的时间。\u003c/p>\u003cp>行动步骤（how）\u003c/p>\u003cp>我们应该如何用“34枚金币时间管理法”记录我们的时间呢？\u003c/p>\u003cp>1、\u003cstrong>每天睡前1小时，数一下你今天花了多少金币\u003c/strong>\u003c/p>\u003cp>每天睡前30分钟，记录你一天的金币数量。如果你今天睡了8小时，清醒16个小时，那么你花了 32枚金币。\u003c/p>\u003cp>\u003cstrong>2、接下来，记录你每一枚金币的用途\u003c/strong>\u003c/p>\u003cp>数完之后，回想你每一枚金币都是怎么花掉的，如：上午9点-10点写一篇文章用掉2个金币，晚上8点到10点看一场电影用掉4个金币等等，如果有遗忘的怎么办，遗忘的部分都可以标记为浪费的时间。\u003c/p>\u003cp>这样做完记录，你就会知道：你做某一件事需要多长时间；一天有多少时间是空白，被浪费的。这样你才能对自己时间的使用有一个清晰的认识，才知道应该在哪些方面优化和改善。\u003c/p>\u003cp>\u003cstrong>举例说明：\u003c/strong>\u003c/p>\u003cp>我以前经常感觉自己时间不够用，感觉工作效率低下，每天都需要加班，很烦。因为想改变这个状况，于是给自己订了很多计划，例如：每天运动1小时，看书1小时，每周认识一个新朋友，等等等等，但总是完不成。我不知道问题出在哪里。\u003c/p>\u003cp>后来我尝试用34枚金币记录自己的时间，发现一天中，沟通占去了2小时，开会占去2小时，处理杂务又占了2小时，真正静下心来做事的时间只有2小时，所以不得不加班。\u003c/p>\u003cp>通过时间记录我发现，沟通和开会太浪费时间，于是我在沟通时，给自己明确沟通目标，设时间提醒；尽可能推掉不重要的会议，并向老板建议提高会议效率，这样节省出2-3个小时的时间。时间就大大优化了。\u003c/p>\u003cp>适用边界：（what）\u003c/p>\u003cp>这个方法是用来记录我们时间的使用，找到时间浪费的源头的，就像医生把脉一样，他只告诉我们哪里有问题，并不能让我们一下子治好病，想做好时间管理，我们还是要吃药的，哈哈。当然关于完整的34枚金币时间管理法，我们有机会再介绍。\u003c/p>\u003cp>接下来让我们巩固一下今天学到的方法，进入我们的应用环节。\u003c/p>","interaction":null,"flags":{"r":true,"i":true,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1542888372000,"updated_at":1542888372000},{"id":4104,"topic":"利用好下班前的10分钟，为你的人生增值","learn_goal":"能利用好下班前的闲暇时间，为当天的工作做个工作及第二天的计划","remark":"离下班差不多只剩下10分钟了，手头上的工作也差不多结束了，晚上约了一个朋友吃晚饭，在这短短的10分钟内，你会做些什么了，是赶紧把东西收拾好，坐等下班，还是把手机掏出来，刷刷朋友圈，和许久不见的朋友微信联系下。是不是觉得这10分钟无关紧要呢？你可千万不要小看了这10分钟哦，如果利用好了，可以为你的人生增值。11月26号我们一起来学习下如何利用好这10分钟，为我们的人生进行增值的秘密吧！","level":"TF2-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"吴印梅","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"学习目标：在跟随我完成本次RIA现场学习后，学习者能够利用好下班前空出来的闲暇时间为自己的当天（本周/本月/本年）工作做好总结及为第二天（周/月/年）的工作做好准备。\r\n大家好，我是吴印梅，现在是一名一级拆书家。在正式开始今天的拆书之前首先要和大家介绍下今天要拆的这本书《如何掌控一年的8760小时》。作者是张雪峰，对于张雪峰，可能很多人都没有听过他的名字，对他并不熟悉，他自己是一家上市公司的董事长，同时还担任了多家知名企业的战略顾问。\r\n因此这本书和其他时间管理类的书相比，有2个特点，一是全面。它几乎集合了市面上所有时间管理书的技巧。第二点是实战，每一个时间管理方法的后面都有详细的操作步骤，而且这些方法都是作者亲自实验过有效的。\r\n如果你总是觉得时间自己不够用，制定的目标没达成，没有时间去学习，那建议你一定要看下这本书，这本书会教你怎样轻轻松松的管理好自己的每一小时。","ratings_count":0,"texts":[{"id":7071,"quote":"\u003cp>利用好下班前的十分钟\u003c/p>\u003cp>我们发现,在办公室中,许多人快到下班的时候就心不在焉了。其实,下班前的10分钟是“黄金时间”,用好了,可以起到“承前启后”的作用。如果你之前的下班前10分钟总是无所事事,从现在起不妨试试下面的几条建议:\u003c/p>\u003cp>1整理备忘录\u003c/p>\u003cp>备忘录上记载了一天的工作摘要,包括当天会见的人士,新获得的名片资料等。内容多半繁杂无章,故在一天工作结束前将它整理一下。这样不但能掌握当天的工作进展,也便于日后翻阅。\u003c/p>\u003cp>2.检查工作表\u003c/p>\u003cp>当天应进行的工作项目,已完成的做上记号,对未完成的项目也做到心中有数\u003c/p>\u003cp>3.检查邮箱\u003c/p>\u003cp>在下班前的十分钟,你可以检查一下自己的邮箱,看看有没有接收到新的邮件,有没有什么重要邮件被错过了,很多企业里,一些管理者因为上班时间很忙,他们会在下班前的时间内给他人回邮件,所以,如果你的领导有什么重要的事交代给你的话,也许会发到你的邮箱。\u003c/p>\u003cp>4拟订次日的工作表\u003c/p>\u003cp>把当天的工作表检查完毕后,接着列出次日应进行的工作项目,拟订工作表。此时可参照备忘录,以防疏漏。\u003c/p>\u003cp>5反思工作\u003c/p>\u003cp>很多人在一段时间工作以后绩效没有提高,但往往找不到原因。其实,你可以利用下班前的十分钟时间反思自己,有时,每天一点小失误就可能在无形中导致大失误,而自己却未曾发现。采取每天反思自己的方式,能够让职场人牢记自己每天的具体工作细节,方便以后的工作总结。\u003c/p>\u003cp>6整理办公桌\u003c/p>\u003cp>下班前将办公桌整理得干干净净,才算真正结束一天的工作。你需要整理的有:别人递上来的新名片、新做的报表,别人给你的重要文件等。是否都放在了合适的地方,那些需要锁好的物品,是不是放进了抽屉?另外,你还可以主动把办公室的垃圾倒出去,清洗自己的茶杯等,这样不至于在下班前没有事做,而且第二天看见整齐的办公桌也会心情大好。在工作中,我们听到很多人抱怨时间不够,其实是浪费的时间太多能充分利用的却很少。人生的每一分钟都值得好好利用,下班前的十分钟看上去不起眼,但如果我们能充分利用起来,一定能在日积月累的工作中发挥重要的作用。\u003c/p>","explains":"\u003cp>和大家先分享一下，我有一个同事姓王，我们都叫他老王，从我们公司离职了，进入了一家做传统行业的公司，他有一次回来看我们，我们就问他说“老王，你在新公司做的怎么样了”，他和我们分享说，他们公司从来不加班，都是踩着点上下班的，离下班还有十几分钟呢，就已经开始收拾桌面，整理好东西等着下班了。很多人都是这样的工作状态对吗？一看到还有10分钟就要下班了，觉得今天工作也差不多了，收拾收拾东西早点走人吧，晚上还约了一个朋友吃饭呢？\u003c/p>\u003cp>Why:可能很多人都觉得不就10分钟嘛，都无关紧要了，事实上，别小看了这10分钟，用好了它可以为我们的人生增值。如果我们把这10分钟利用好，不仅可以对我们当天的工作做个梳理，同时还能为明天的工作做好准备，提高工作效率。（\u003cstrong>这样做的好处\u003c/strong>）\u003c/p>\u003cp>What:这个片断就是教我们怎么去利用好下班前的10分钟，为当天的工作做好总结和第二天的工作做好准备的。\u003c/p>\u003cp>How:作者给出了6个建议：\u003c/p>\u003cp>1.&nbsp;整理备忘录，既能掌握当天的工作进展，也方便以后的翻阅。\u003c/p>\u003cp>2.&nbsp;检查工作表，知道自己当天哪些工作已经做完了，哪些还没做完\u003c/p>\u003cp>3.&nbsp;检查邮箱，看看自己是否有什么重要的邮件要处理\u003c/p>\u003cp>4.&nbsp;参照备忘录制定第二天的工作计划\u003c/p>\u003cp>5.&nbsp;反思这一天的工作\u003c/p>\u003cp>6.&nbsp;把办公桌整理干净。\u003c/p>\u003cp>首先要和大家说下，这这里所说的10分钟并不是真的指狭义的10分钟，是指广义的概念，是指你比较闲暇，比较无所事事的时间，可能不到10分钟，也可能是长达半个小时，甚至是一个小时。比如说在我们公司，是做电话营销的，下班时间是6点，现在是冬天了，很多公司5点就下班了，如果说超过5点你再打电话过去，人家就会骂你，说都下班了，你们还打电话。所以在我们公司一般到了5点就基本上不打电话了，就在开始整理客户资源，聊聊天，发微信......\u003c/p>\u003cp>另外会不会有人觉得现在大家有事情都发微信了，邮箱都很少用了，没有必要每天去检查邮查呢？其实还是很必要的，大家可以想想自己手上有多少个微信群，像是工作群，家人群，学习群......是不是经常很多微信信息都没来得及看呢？再加上微信信息太多，查找起来很麻烦，也很容易丢失，所以一般公司有比较正式事情，文件都是通过邮箱传达的。就像我们公司一般的事情基本上都是通过微信群传达的，虽然领导，行政经常在群里@我们，要我们收到回复，但基本上我们不太会看下领导具体发了啥内容，就是看到前面的人回复，后面的人就跟着回复，都不去看内容的。下次领导如果说起来XX事情怎么样，我们都一脸懵逼的问，啊？什么事情啊，不知道啊。所以一般遇到比较重要的事情公司还是通过邮箱去传达的。\u003c/p>\u003cp>再次总结下，这个片断时教我们利用下班前的10分钟为我们当天的工作做个总结，同时也为第二天的工作做好准备。如果我们没有利用好这短短的10分钟，就任由它浪费了，大家可以想下会怎么样？首先我们的时间没有得到充分的利用，第二，拉低我们第二天的工作效率，因为有些事情你今天不去做，明天还是要去做的。（\u003cstrong>不这么做的坏处\u003c/strong>）\u003c/p>\u003cp>大家有没有发现，这里面的方法不只适合在下班前的10分钟用，也适合在其它时间，你有空闲时间的时候，比如说你坐车去拜访一个客户，那是不是也可以利用坐车的空闲时间整理下手机上的备忘录，看下今天还有哪些事情没处理好。哪些事情可以直接在坐车的时候就用手机去处理的呢？\u003c/p>","interaction":"\u003cp>A2：设想下明天工作日快要下班的时候，下周末放假的前一天，2018年年假前的一段时间.....,你觉得哪个时间你的工作最容易不饱和，最容易无所事事，浪费时间？请大家用1分钟的时间和小组内的伙伴分享下。等下我们再请人来分享。\u003c/p>\u003cp>参与者A：过年前的10天左右，因为我们做这行，过年前的10天工厂，工人都放假了，我们工作上就不会有什么其它安排了。\u003c/p>\u003cp>参与者B：我一般是星期五（上班的时候），因为周六周日双休，到星期五就有点疲软了，不愿意去动脑，不太会去想工作上的事情。\u003c/p>\u003cp>参与者C：我很认同他（参与者B），一想到明天是周六了，我感觉哎呀，放松了。\u003c/p>\u003cp>现在进入第二步，请大家再分享下，在你刚刚说到的那个时间段内，当你正在无所事事，正在浪费时间的那个时候，你突然觉得自己不能再这样下去了，这样简直是在浪费生命嘛！我应该高效的利用好每一分钟。这个时候你想到今天的拆书里的这个片断，你觉得你可以利用片断中的哪法方法为你的人生增值呢？请大家再和组里的小伙伴分享下，用2分钟的时间，等下我们再请人来分享下。\u003c/p>\u003cp>参与者A：我可能会做些工作的梳理，这个项目进行到哪一步了，我得想一想，可能会出现什么问题，考虑下具体后面怎么推进，备忘录的话，可能是供应商方面的我整理一下。工作表关于每个项目的进度。邮箱关于清单，报价方面的我肯定要整理一下。工作出了什么问题，我可能会反思一下。\u003c/p>\u003cp>参与者C：周五下班的前的一个小时之内，可能人心是比较浮躁的，出发点就是自律给你自由，你走心的在这个时间段利用好之后对你下一步的价值是一个很好的提升，是别人所不具备的，我将要做的就是三点：\u003c/p>\u003cp>1，办公桌的常规文件的整理和规档，因为是一个结束的阶段，下一周的重新开启。\u003c/p>\u003cp>2，思考下下周的工作，计划下下周怎么安排，因为周五是承上启下比较清楚的。周一的的话怕有遗漏，及时记几笔，降低失误率。\u003c/p>\u003cp>3，现在的QQ和微信信息非常多，而且常常是流水式的，如果是在周五或平时有心的时候，把一些重要的信息用手机拍照拍下来，那周五的时候把它存在一个地方，这样对你未来一个月如果再涉及到这一点，你再回去找的时候会便捷很多。\u003c/p>\u003cp>总结：因为今天时间有限，我就不请每个人都分享了，等下私底下再分享下，做个总结，我们公司有句话，一直在讲的“一年之际在于冬，一日之际在于昨”，也就是说你前一天做好工作计划，第二天当别人都在做计划的时候，在准备东西的时候，你已经在开始工作了，你就能先别人一步，一步先，步步先。希望大家都能有个高效率的工作，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1511697527000,"updated_at":1513763773000,"ria":true},{"id":3994,"topic":"如何制定一个可实现的短小目标","learn_goal":"学习者能够在限定的时间内达成自己制定的短小目标","remark":"在做事情的过程中，一些人总是表现出急躁的毛病，事实上，任何一件事，从计划到实现的阶段，总是要有一个时间阶段的。如果我们想一步登天的话，那么，经常会遭到破坏性的阻碍。因此，无论如何，我们都要有耐心，我们可以把大目标进行拆解成一个个可实现的短小目标，短小目标要怎么制订呢？我们一起来学习下吧。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"吴印梅","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，我是拆书家吴印梅。首先要和大家介绍下今天要拆的这本书《如何掌控一年的8760小时》。作者是张雪峰，可能对于张雪峰，很多人都没有听过他的名字，对他并不熟悉，他自己是一家上市公司的董事长，同时还担任了多家企业的战略顾问。\r\n这本书和其他时间管理类的书相比，有2个特点，一是全面。它几乎集合了市面上所有时间管理书的技巧。第二点是实战，每一个时间管理方法的后面都有详细的操作步骤。\r\n如果你总是觉得时间不够用，制定的目标没达成，没有时间去学习，那建议你一定要看下这本书，这本书会教你怎样轻轻松松的管理好自己的每一小时。","ratings_count":0,"texts":[{"id":6946,"quote":"\u003cp>　&nbsp;如何制定一个可实现的短小目标\u003c/p>\u003cp>其实，和锻炼身体一样，做任何事情，都不可能“一口吃成一个胖子”。我们可以先为自己定一个可以轻易实现的目标，这个目标的实现能增强我们自信心，帮助我们成功破解难题。\u003c/p>\u003cp>具体来说,这需要我们做到:\u003c/p>\u003cp>1要为目标设定一个可以做到、同时又有一定挑战性的期限\u003c/p>\u003cp>比如,如果你的目标是写一本书,但是你并没有给自己一个期限那么,你就会无限制地拖延下去,直到生命的终结。而如果你给自己定一个期限,比如一年,或者两年、三年,那么你就会按照这个期限来约束自已,在规定的时间内完成任务。\u003c/p>\u003cp>当然,我们所设置的这个期限需要有一定的紧迫性,才能鞭策自己。但同时还得合理,任何一件事的完成都不可能一步登天。\u003c/p>\u003cp>2将你的目标切割、划分\u003c/p>\u003cp>很多人都有个缺点,那就是理想化。比如,他们会幻想灰姑娘与王子的故事,会幻想财富从天而降等,他们在制订人生规划与学习计划的时候,偶尔也会有点好高骛远,但不能奢望一口吃成个胖子,一锹挖好一口井。比如你现在月薪是2000元,你就不能奢望一下子涨到20000元,那是不切合实际的。你可以设定到3000元、4000元,然后慢慢地接近10000元,最后达到20000元。\u003c/p>\u003cp>这就是一种将目标切割的方法。凡是长远的目标都需要较长时间来完成,且有一定的难度,如果开始你只照着这个长远目标努力,短时间内不会收到成效,这会挫伤你的积极性。所以要把长远目标分解成无数小目标,这样更容易达成。每天都进步一点,可以鼓励自己,提高自己的积极性,向终极目标又迈进了一步。\u003c/p>\u003cp>3.不断总结问题\u003c/p>\u003cp>任何事做起来都会遇到或多或少的困难,在制定目标时,不妨把可能出现的困难加以例证,对困难先有一个心理准备,做一些必要的防范,在真正碰到困难时才不会手忙脚乱。当然,很多困难都是无法预知的,最关键的还是要有战胜它的决心,以积极的心态想方设法去解决,才会让事情有转机。\u003c/p>\u003cp>4.处理好时间问题\u003c/p>\u003cp>你可以问问自己:这个任务事实上将花去我多少时间?我真正能抽出多少时间投入其中?不是:明天我有充足的时间去做这件事。而是:我最好看一下我的日程表,看看我什么时候可以开始做。上次那件事花的时间超出了我的预期。\u003c/p>\u003cp>5.保护你的时间\u003c/p>\u003cp>学会怎样说不,不要去做额外的或者不必要的事情。不是:我必须对任间需要我的人有求必应。而是:在工作的时候,我没必要接听电话。我会收看留言,然后在我做完事情后再回电。\u003c/p>\u003cp>6不要找借口\u003c/p>\u003cp>不要习惯性地利用借口来拖延,而要将它看作再做15分钟的一个信号。或者利用你的借口作为完成一个步骤之后的奖赏。不是:我累了,或者是我饿了、很烦躁等,我以后再做。而是:我累了,所以我将只花15分钟写报告,接下来我会小睡片刻。\u003c/p>\u003cp>7奖赏自己获得的每一个小进步\u003c/p>\u003cp>如果你实现了初步的计划,那么,你就应该奖赏自己,当然,你更应该关注自己的努力,而不是结果。比如,你可以奖励自己看部电影。\u003c/p>\u003cp>在做事的过程中,一些人总是表现出急躁的毛病,事实上,任何一件事,从计划到实现的阶段,总有一段所谓时机的存在,也就是需要一些时间让它自然成熟。如果我想一步登天的话,那么,经常会遭到破坏性的阻碍。因此,无论如何,我们都要有耐心,你可以暂时为自己制订一个可实现的短小的目标。\u003c/p>","explains":"\u003cp>好，大家片断都看完了，下面是I环节，拆书家用自己的语言重述下这个片断\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>上个月的时候我突然迷上了占星，然后就去喜马拉雅买了很多关于占星的讲座，又去当当网买了本占星书。那几天只要一有时间就去听喜马拉雅的讲座，不管是走在路上的时候还是在吃饭的时候。恨不得3天就能学会怎么去分析星盘。但是在听了几天之后发现自己什么都没记住。后来因为其它事情，就把这件事情给搁置了。其实我们生活中经常会有这样的事情发生对吗？给自己制定了一个很大的目标，恨不得马上就能达成这个目标，但是因为遇到种种挫折和问题，结果目标都没有完成，心里很受伤。对目标失去了信心。\u003c/p>\u003cp>这个片断就是教我们怎么去制定一个容易达成的短小目标的。\u003c/p>\u003cp>如果我们目标太远大，没有把它分解成容易达成的短小目标，看着就遥遥无期，很难达成，我们就会动力不足，给自己找各种借口，去拖延。\u003c/p>\u003cp>作者在这个片断中给出了制定了可实现的短小目标的方法，这种方法适合于所有小目标的制定和达成，具体方法是：\u003c/p>\u003cp>（1）设定一个期限，这个期限是可以做到，但是又有一定的挑战性的。有了这个期限可以鞭策我们在规定的时间达成目标。\u003c/p>\u003cp>（2）把大目标切割成更容易达成的小目标。\u003c/p>\u003cp>（3）在制定目标时先对可能遇到的问题做好心理准备，做一些防范。\u003c/p>\u003cp>（4）预估这件事情要花多少时间，留一个专门的时间做这件事情\u003c/p>\u003cp>（5）在这个时间段只专注做这一件事情，不做额外的事情。\u003c/p>\u003cp>（6）不要找借口拖延，把借口变成完成之后给自己的奖励。\u003c/p>\u003cp>（7）每达成一个小计划，给自己一个奖励。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>你们有没有过这样的经历，兴冲冲的给自己制定了一个目标，结果最后目标没有达成，你心里很失落。现在给大家3分钟的时间在各自小组内分享下这个目标是什么？当时你们是怎么去制定这个目标的。等会我们再请人来分享下，好！现在开始：\u003c/p>\u003cp>1号参与者：我是一个时间践行者，我现在遇到一个最大的惑，我的目标坚持100天的脚部恢复训练，并且在群里面打卡，现在已经过了一半了，50天了，我做了48天，还有2天没有做到，为什么呢？因为发烧了，我实在是起不来，也做不了这个训练。所以我觉得做计划的时候也要把意外的因素也要考虑进去。\u003c/p>\u003cp>2号参与者：因为体脂有点高，我想降点体脂。就研究了各种健身教程。觉得那个63天的计划挺好。对健身来说，63天是挺短的一个周期，如果63天坚持下来，我的体脂应该会降很多下来。这个教程是一个星期做6次，一天的休息时间，我第一天熬过去了。却实很累，做完之后倒头就睡，第二天起来还会酸痛的那种。等到第二个星期的时候，中间有一天，我忘了是因为什么原因，反正就是给自己找了一个借口，那一天没有去做，等到第二天就没有动力做下去了。不知道为什么，一点动力都没有。所以一整个63天的计划就搁置了。\u003c/p>\u003cp>A１+：如果说现在让你们坐上时光机，嗖的一下就回到过去了，回到你们刚开始制定计划的那个时间，你们运用片段的制定目标的方法，你们会重新去制定这个目标？可以先用2分钟的时间在纸上写下，到时候我们再请人来分享下：\u003c/p>\u003cp>1号参与者：首先第一点，根据我锻炼的情况，我会适当的增加训练时间，比如说一天增加5分钟，逐步的进行恢复；二，为了保证一天最低半小时，早上起来第一件事情（除了洗脸刷牙）就是做腿部的训练，这样能把时间处理好，也能保护我的时间不受其他事情的影响。三，做总结，考虑一些意外的因素，比如说发烧的情况，还有就是刮风下雨，要有一个替代方案，如果说户外做不了，户内可不可以去做。四，不要找借口，原先我们在时间管理上有一个很好的方法，如果没有做到就在群里发一个红包，这样能让不找借口。最后如果确实做到了，给自己一个奖励，也让自己对成功有一个更好的期待。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1510477315000,"updated_at":1510477315000,"ria":true},{"id":2923,"topic":"找到自己人生的目标","learn_goal":"通过角色定位找到自己人生的目标","remark":"一年是365天，但如果是8760个小时呢？\r\n在《你一年的8760小时》里，艾力以“34枚金币时间管理法”为核心，探讨从努力到如何努力的思维转变，并具体介绍了设定人生目标、激发个人潜力、时间管理、困境突破、人际关系5个重要面向行之有效的方法。\r\n励志有方法，梦想可变现。真正有效的方法会为梦想添上最有力的翅膀。","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"John","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"本次目标是在跟随我完成本次RIA现场学习后，学员可以理解人生目标的重要性并且可以通过角色定位的方法找到自己人生目标；\r\nF《你一年的8760小时》作者是艾力，新东方18000教师中的12位顶级集团讲师之一。曾经是参加过超级演说家，奇葩说，是理性与自律的化身，他创造了34枚金币的时间管理方法，影响了一大批人，是时间管理初级入门的一本好书。你拥有的不是365天，而是8760个小时。每一个小时，你都在改变自己 ，每一个小时，你都在走向梦想。\r\nA与其他的时间管理和励志类图书相比，本书最大的优点有两个，第一是浅显易懂；第二作者的观点是建立在大量阅读相关致用类图书和实践的基础上的。这两点让这本书可以更容易的帮助到你。\r\nB日子过的很紧凑，但是貌似又没有充实感？每天都在努力，却不知道自己的努力朝向何方。如果你也有这样的场景，那通过今天这两个片段的学习，希望能帮助大家找回些许方向，让我们明白重要的不是努力，而是努力的方式。励志有方法，梦想可变现。今晚，我们将通过角色定位的方式找到自己生命的灯塔。","ratings_count":0,"texts":[{"id":5709,"quote":"\u003cp>R0（配乐朗读）\u003c/p>\u003cp>　没有方向，怎么走都是游荡\u003c/p>\u003cp>　　现在，我希望你能放下手头所有的工作，点开一首舒缓的略带小清新的音乐，和我一起运用想象力来做一件有意义的事。\u003c/p>\u003cp>　　想象一个美好的周末清晨，你在九十点钟醒来，阳光明媚，周身舒畅。打开窗户，呼吸到新鲜的空气，放眼望去，一片新绿。这是一个没有工作、没有压力的周六的早上。\u003c/p>\u003cp>　　起床之后的你和自己心爱的人，可能是家人，或是那个ta，共进早餐，吃的是你最爱的食物。接下来你们打算一起去旅行。\u003c/p>\u003cp>　　你们一起驱车前行，周末城市的郊外宁静而美好，充满梦幻的色彩。谈笑间，你们来到了一座欧式风情的白色木屋前。\u003c/p>\u003cp>　　里面人头攒动，你们决定进去一探究竟。你突然发现，屋里居然站满了与你的生命息息相关的所有人。家人、朋友、同学，一切你所珍视的人都在这个房间里。你很吃惊，但是似乎没人发现你，大家目光平静，互相交流着。\u003c/p>\u003cp>　　你想和他们打招呼，但大家对你视而不见、听而不闻。于是你站在一旁，在一定距离之外静静地打量着。过了一会儿，所有人都入座，逐一站在台前发言、分享。你没有仔细听大家在说什么，只是很好奇。过了一阵你发现没人上台去讲话了，于是你决定走到台前把自己的想法也和大家分享。\u003c/p>\u003cp>　　你站起身来，带着些许紧张和忐忑，但还是保持着向前的勇气。一步、两步、三步、四步、五步、六步、七步，七步之后，你站到台前，转过身面对大家，深吸一口气，准备说出心中所想。\u003c/p>\u003cp>　　正要开口，你突然发现在你右手边不远处的桌上放着一个木盒。你很好奇，之前并没有注意到它，你想去看看里面到底装着什么。\u003c/p>\u003cp>　　你正打算打开盒子，却看到了盒子上有一张你的黑白照片，肃穆而沉重。抬头一看，头顶横幅上写着一行字：沉痛悼念×××。\u003c/p>\u003cp>　　没错，这就是你的葬礼\u003c/p>\u003cp>　　读到这里，你可能以为自己买错书了，怎么一本励志书变成了一部悬疑小说？但如果刚才你在阅读时真的将自己代入这个场景，那你或许会经历些许灵魂的洗礼。——这也是国外流行的“墓园疗法”的一个环节。\u003c/p>\u003cp>\u003cstrong>（前面这部分配乐朗读）\u003c/strong>\u003c/p>\u003cp>不要停下来，你还在葬礼中，一个会在五十、六十、甚至是一百年后真实发生的葬礼。从古至今，一个人自出生那刻起，便是向死而生，任何一个人都不能逃离死亡的命运。\u003c/p>\u003cp>我们希望在生命结束时，如何回顾自己一生的得失？又希望别人在我们的葬礼如何悼念自己？\u003c/p>\u003cp>&nbsp; 每个人终将离开这个世界，在我看来，生命的意义蕴与当下的每一个时刻和每个选择中。假设明天是你的生命的最后一天，你是否还选择做你当下从事的事情？是否能坦然离开这个世界。\u003c/p>","explains":"\u003cp>互动 大家看到这个片段什么感触？\u003c/p>\u003cp>预防异议 异议：一定要用这种让人不舒服的葬礼的方式进入吗？\u003c/p>\u003cp>这是国外流行的墓园测试法。从古至今无人能逃离死亡的结局，通过这个小场景的设定，能够更好地帮助我们以终为始的思考人生这个大问题，而做这样的思考对我们每个人来说都是至关重要的。\u003c/p>\u003cp>what\u003c/p>\u003cp>人生宏大，但是评价人生无非是两个方面，你自己怎么评价你的一生，你希望别人怎么评价你的一生。（当然如果你是基督徒，还要加上更重要的就是上帝如何评价你。）\u003c/p>\u003cp>我们每时每刻做的事情，决定，都将或多或少的影响自己的人生目标，或前进或后退。就像我们开场活动一样，今天你来拆书的目标是什么，与你的人生目标是相悖还是同向。\u003c/p>\u003cp>why\u003c/p>\u003cp>通过思考自己的悼词，可以有效的提醒我们人生方向的重要性，而有效地梳理自己的人生方向有助于帮助自己做好更多的人生选择。当我们遇到重大决定时可以通过与人生目标相比较作出理性的决定。人生方向这个命题很大，突然问起，估计很少能有人迅速全面的回答出来，可是通过这样一种方法，可以引发我们的思考，促使自己更好的明确。\u003c/p>\u003cp>结合原文脉络给出更贴切地例子\u003c/p>\u003cp>书中提到我们希望生命结束时，自己如何回顾以及别人如何悼念。我给出一个我的例子：我是John的学生，打我认识John那天开始，他就是我的人生导师。他热情，理性，充满智慧，并且在我需要的时候他总是可以来帮助到我，他总是愿意让我进入他的生活，让我看到他在为人父，为人夫，为人子，为人友，为人师方面所做的近乎完美的榜样。\u003c/p>\u003cp>How\u003c/p>\u003cp>思考自己希望在生命结束时，如何回顾自己一生的得失，又希望别人在我们的葬礼如何悼念自己。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>大家回想一下，在你过往的经历当中，有没有曾经想过这个终极的问题，希望在生命的终点，自己和别人如何评价自己的一生？如果没有，想想会不会自己的人生缺乏方向？这带来了哪些影响？如果有，当时你是怎么想的？给大家2分钟时间思考，你可以写下关键词。（1分钟）\u003c/p>\u003cp>请1位分享（1分钟）\u003c/p>\u003cp>案例：\u003c/p>\u003cp>学员A：我会常常思考这儿问题以便于对我现在的生活做出指导。\u003c/p>\u003cp>比如我会想我最终要有自己的企业，所以我一定会创业，那么我要在三十五岁开始创业，然后我就倒推我什么时候应该做什么样的准备。\u003c/p>\u003cp>A1+\u003c/p>\u003cp>接下来趁热打铁，我们再想假如时间可以倒流，你有机会回到早年，你可以重新思考你的人生，你会做哪些调整？如果你没有思考过的，那么这是一个机会。可以参考文中的提示：希望在生命结束时，如何回顾自己一生的得失，又希望别人在我们的葬礼如何悼念自己。你可以从他人的角度来写一篇自己的悼词。这个悼词要求，开场表示你的角色（就是和被追悼者的关系，比如我是John的同学），描述这个角色和被追悼者之间的故事，并总结他的优秀品质和闪光点。（3分钟）\u003c/p>\u003cp>案例：\u003c/p>\u003cp>学员Y：我是y的朋友，在初中的时候我们就认识了，她温柔善良善解人意，跟她认识这么多年，从来没见她吹毛求疵过，对于朋友的需要她总是愿意伸出援手。对于她的离去，我深感悲痛，愿她在天堂一切都好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":5711,"quote":"\u003cp>每个人在生命中都扮演着不同的角色，随着年龄的增长，角色也在增加。小时候我们扮演的角色很少，压力自然也小。\u003c/p>\u003cp>时常不自知的是，我们经常只记得年龄的增长，却忘记了角色在增加。有时候太过专注于一个角色，却忘记了这个舞台还有太多的角色等待着我们。\u003c/p>\u003cp>因此，确定了自己的人生方向后，还要把它具体化为人生目标，才能让我们追求的生命的意义真正落地。\u003c/p>\u003cp>人生目标的确定可以说是一门绝对的技术活。既要能仰望星空，又得脚踏实地。在尝试过不同的计划、目标制定方法后，我发现用史蒂芬.柯维在《高效能认识的七个习惯》中提到的角色定位的方法来确认人生目标最方便，最有效。\u003c/p>\u003cp>每个人都在生活中承担着不同的角色，我们需要在不同的角色里确认各自的目标，让这个目标贴合我们人生的愿景。这样我们既能保证人生中重要的事都有个可以信赖的方向，也能保证人生不会因为过于集中某一两件事情而失去平衡，反受其害。\u003c/p>\u003cp>从今天开始，列一份角色与目标的清单，每天、每周、每个月回顾一下，不将目光只局限于一点，而是宏观考量自己的各种角色和定位，并时时自我修正。\u003c/p>\u003cp>你的人生将变得不同。\u003c/p>","explains":"\u003cp>互动\u003c/p>\u003cp>读完片段后，大家觉得这段有什么关键词？或者对你触动比较大的地方？\u003c/p>\u003cp>why\u003c/p>\u003cp>我们困惑为什么小时候无忧无虑，可随着年龄的增加，压力越来越大。比如：小时候努力学习就能被表扬，但现在单单努力工作已经无法满足了，照样还会被爸妈，爱人埋怨等等。原因很简单，我们的角色增加了，而我们往往太过于专注于一个角色，而忽略了其他更重要的角色，从而使得我们的生活失去平衡。\u003c/p>\u003cp>不这么做的坏处\u003c/p>\u003cp>其实生活中大部分不会对自己的人生做长远的规划，这样的人结果常常是随波逐流的；或者即使有的人想规划或者规划了，但是由于方法不当，得出的规划也不能付诸实践，这种没有结果的规划会带来负面的反馈，就是规划没用。当生命没有规划明确的目标时，我们会面临一系列重大问题，比如我们可能在家庭生活中毫无幸福，工作没有成就感，自己和他人对自己的评价也趋于负面或者平庸。。。\u003c/p>\u003cp>what（包括概念举例对比）\u003c/p>\u003cp>人生目标既要仰望星空又要脚踏实地。\u003c/p>\u003cp>仰望星空就是要让自己有所期许，我们的目标必须让自己羡慕，想想都觉得美。\u003c/p>\u003cp>结合原文脉络给出更贴切的例子：比如为家人提供基本衣食住行的供给就不够仰望星空，而作为爸爸，在爱和勇敢追求梦想方面为孩子做榜样就拔高了许多。\u003c/p>\u003cp>脚踏实地是让自己能力及行动，不要觉得好像没地方下脚，不知怎么开始。\u003c/p>\u003cp>结合原文脉络给出更贴切的例子：比如，我要实现中华名族的伟大复兴就不是好的人生目标，而在公民角色上，尽心履行宪法赋予我的职责就更靠谱一点。\u003c/p>\u003cp>how细化行动步骤\u003c/p>\u003cp>列出你在生活中承担着的角色\u003c/p>\u003cp>将角色按照重要程度排序\u003c/p>\u003cp>将自己生活中的重要角色都设定目标。\u003c/p>\u003cp>定期回顾修正 一次制定完成后，一定不会很完整全面，另一方面很快就会忘记，所以要定期回顾修正。\u003c/p>","interaction":"\u003cp>A3现场演练\u003c/p>\u003cp>写下你在你的生命中所扮演的角色，越多越好，不要停。\u003c/p>\u003cp>认真思考你所最看重的3-5个角色，你可以用打分的方式，10分最高，1分最低，给每一个角色打分，然后挑出最高的几个。\u003c/p>\u003cp>根据刚才的拆解按照书中的方法，给每个角色设定目标。这个目标就是我们百年之后，该角色所对应的人在我们追悼会上的陈述。\u003c/p>\u003cp>然后标注一个合理的日期进行回顾修正。\u003c/p>\u003cp>学员分享&nbsp;\u003c/p>\u003cp>学员Y：\u003c/p>\u003cp>角色：自己，女儿，朋友，下属，领导，销售，同学，老师，采购，女朋友，妻子，妈妈。\u003cbr>\u003c/p>\u003cp>最重要的三个角色及其目标。\u003c/p>\u003cp>朋友：温柔善良善解人意，不吹毛求疵，对于朋友的需要总是愿意伸出援手。\u003c/p>\u003cp>女儿：孝敬，贴心，供给，安慰。\u003c/p>\u003cp>下属：支持，执行，任劳任怨。\u003c/p>\u003cp>A3现场角色扮演\u003cbr>\u003c/p>\u003cp>两两分组，结对演练。\u003c/p>\u003cp>每人快速分享一下最重要的三个角色\u003c/p>\u003cp>角色是孩子，场景是父母催婚；\u003c/p>\u003cp>角色是父母，场景是与自己的父母关于育儿产生了不同的看法，沟通中。\u003c/p>\u003cp>角色是领导，场景是遇到了一个不服从命令坚决认为自己才是对的。\u003c/p>\u003cp>角色是下属，场景领导无端指责自己。\u003c/p>\u003cp>请思考根据你的角色定位，你要现场如何应对以及后续处理？\u003c/p>\u003cp>陪练总结和感受\u003c/p>\u003cp>案例：\u003c/p>\u003cp>学员Z的角色是领导，角色目标是：支持和帮助员工职业发展，帮助员工克服工作中困难。\u003c/p>\u003cp>Y：我不认为你的这个方案是合适的，员工绩效考核就应该由HR绩效组同事说了算，为什么要屈就业务部门？并且我们已经给他们机会反馈，那时候不说话，现在都要上线了，有问题。他们又不懂绩效。\u003c/p>\u003cp>Z：Y我知道你现在时间紧张了，如果跟业务部门做沟通调整时间势必要加重工作量。\u003c/p>\u003cp>Y：对呀，而且这都是他们的问题。\u003c/p>\u003cp>Z：你觉得我们做绩效工具是给谁用的？\u003c/p>\u003cp>Y：。。。\u003c/p>\u003cp>Z：毫无以为，他们才是我们的客户对吗？客户有时候会有点不配合。如果我们这个时候也不去配合他们，他们最终不会好好用我们的这个产品，最终的结果是双输的局面对吧？\u003c/p>\u003cp>Y：好吧，去听听他们到底要干什么吧。\u003c/p>\u003cp>A2\u003c/p>\u003cp>【分步催化1提问】\u003c/p>\u003cp>请大家思考，在接下来的一段时间里，可以是一个星期一个月三个月，结合一两个最重要的角色，你可能会遇到哪些情景？比如父母常见的情景是孩子不学习或者不听管教，子女常见的是父母催婚管教孩子意见不同，领导跟下属之间出现冲突等。思考一下，写出关键词。（2分钟）\u003c/p>\u003cp>学员分享：\u003c/p>\u003cp>M：接下来我在下属这个角色上应该还是会遇到跟领导冲突的情况，就是大家意见相左，更重要的是，领导认为内勤都是成本，只有销售带来价值，这是冲突的根源。\u003c/p>\u003cp>【分步催化2提问】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 就刚才的情景，结合你给自己的角色和设定的目标，你打算如何做呢？（2分钟）\u003c/p>\u003cp>学员分享\u003c/p>\u003cp>M：我的内勤工作在月初月末的时候相对集中，所以我打算从明天开始，利用月初月末的这个时间努力集中处理内勤。然后中间两个周去参与跑业务，最终转到销售岗位。\u003c/p>\u003cp>结语\u003c/p>\u003cp>通过今天的拆解，是不是都对自己的人生方向明了一点了呢？通过短短一个小时，肯定是不够的，希望大家今天回去后继续不断地完善，并且定期修正，让自己的人生减少一点迷茫，增加一点光彩。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497421382000,"updated_at":1497421382000,"ria":true},{"id":2207,"topic":"人生的目标","learn_goal":"通过角色定位找到自己人生的目标","remark":"F作者是艾力，新东方18000教师中的12位顶级集团讲师之一。他创造了34枚金币的时间管理方法，影响了一大批人，是时间管理初级入门的一本好书。你拥有的不是365天，而是8760个小时。每一个小时，你都在改变自己 。\r\nA与其他的时间管理和励志类图书相比，本书最大的优点有两个，第一是浅显易懂；第二作者的观点是建立在大量阅读相关致用类图书和实践的基础上的。这两点让这本书可以更容易的帮助到你。\r\nB日子过的很紧凑，但是貌似又没有充实感？每天都在努力，却不知道自己的努力朝向何方。如果你也有这样的场景，那通过今天这两个片段的学习，希望能让我们明白重要的不是努力，而是努力的方式。今晚，我们将通过角色定位的方式","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"John","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"F作者是艾力，新东方18000教师中的12位顶级集团讲师之一。他创造了34枚金币的时间管理方法，影响了一大批人，是时间管理初级入门的一本好书。你拥有的不是365天，而是8760个小时。每一个小时，你都在改变自己 。\r\nA与其他的时间管理和励志类图书相比，本书最大的优点有两个，第一是浅显易懂；第二作者的观点是建立在大量阅读相关致用类图书和实践的基础上的。这两点让这本书可以更容易的帮助到你。\r\nB日子过的很紧凑，但是貌似又没有充实感？每天都在努力，却不知道自己的努力朝向何方。如果你也有这样的场景，那通过今天这两个片段的学习，希望能让我们明白重要的不是努力，而是努力的方式。今晚，我们将通过角色定位的方式找到自己生命的灯塔。","ratings_count":0,"texts":[{"id":4871,"quote":"\u003cp>没有方向，怎么走都是游荡\u003cbr>　　现在，我希望你能放下手头所有的工作，点开一首舒缓的略带小清新的音乐，和我一起运用想象力来做一件有意义的事。\u003cbr>　　想象一个美好的周末清晨，你在九十点钟醒来，阳光明媚，周身舒畅。打开窗户，呼吸到新鲜的空气，放眼望去，一片新绿。这是一个没有工作、没有压力的周六的早上。\u003cbr>　　起床之后的你和自己心爱的人，可能是家人，或是那个ta，共进早餐，吃的是你最爱的食物。接下来你们打算一起去旅行。\u003cbr>　　你们一起驱车前行，周末城市的郊外宁静而美好，充满梦幻的色彩。谈笑间，你们来到了一座欧式风情的白色木屋前。\u003cbr>　　里面人头攒动，你们决定进去一探究竟。你突然发现，屋里居然站满了与你的生命息息相关的所有人。家人、朋友、同学，一切你所珍视的人都在这个房间里。你很吃惊，但是似乎没人发现你，大家目光平静，互相交流着。\u003cbr>　　你想和他们打招呼，但大家对你视而不见、听而不闻。于是你站在一旁，在一定距离之外静静地打量着。过了一会儿，所有人都入座，逐一站在台前发言、分享。你没有仔细听大家在说什么，只是很好奇。过了一阵你发现没人上台去讲话了，于是你决定走到台前把自己的想法也和大家分享。\u003cbr>　　你站起身来，带着些许紧张和忐忑，但还是保持着向前的勇气。一步、两步、三步、四步、五步、六步、七步，七步之后，你站到台前，转过身面对大家，深吸一口气，准备说出心中所想。\u003cbr>　　正要开口，你突然发现在你右手边不远处的桌上放着一个木盒。你很好奇，之前并没有注意到它，你想去看看里面到底装着什么。\u003cbr>　　你正打算打开盒子，却看到了盒子上有一张你的黑白照片，肃穆而沉重。抬头一看，头顶横幅上写着一行字：沉痛悼念×××。\u003cbr>　　没错，这就是你的葬礼。\u003cbr>　　读到这里，你可能以为自己买错书了，怎么一本励志书变成了一部悬疑小说？但如果刚才你在阅读时真的将自己代入这个场景，那你或许会经历些许灵魂的洗礼。——这也是国外流行的“墓园疗法”的一个环节。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 不要停下来，你还在葬礼中，一个会在五十、六十、甚至是一百年后真实发生的葬礼。从古至今，一个人自出生那刻起，便是向死而生，任何一个人都不能逃离死亡的命运。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我们希望在生命结束时，如何回顾自己一生的得失？又希望别人在我们的葬礼如何悼念自己？\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 每个人终将离开这个世界，在我看来，生命的意义蕴与当下的每一个时刻和每个选择中。假设明天是你的生命的最后一天，你是否还选择做你当下从事的事情？是否能坦然离开这个世界。\u003cbr>\u003c/p>","explains":"\u003ch3>互动\u003c/h3>\u003cp>大家看到这个片段什么感触？\u003c/p>\u003ch3>预防异议\u003c/h3>\u003cp>一定要用这种让人不舒服的葬礼的方式进入吗？\u003c/p>\u003cp>这是国外流行的墓园测试法，从古至今无人能逃离死亡的结局，通过这个小场景的设定，能够给自己敲响警钟。\u003c/p>\u003ch3>what\u003c/h3>\u003cp>人生宏大，但是评价人生无非是两个方面，你自己怎么评价你的一生，你希望别人怎么评价你的一生。（当然如果你是基督徒，还要加上更重要的就是上帝如何评价你。）\u003cbr>我们每时每刻做的事情，决定，都将或多或少的影响自己的人生目标，或前进或后退。就像我们开场活动一样，今天你来拆书的目标是什么，与你的人生目标是相悖还是同向。\u003c/p>\u003ch3>why\u003c/h3>\u003cp>有效地梳理自己的人生方向有助于帮助自己做好更多的人生选择。当我们遇到重大决定时可以通过与人生目标相比较作出理性的决定。人生方向这个命题很大，突然问起，估计很少能有人迅速全面的回答出来，可是通过这样一种方法，可以引发我们的思考，促使自己更好的明确。\u003c/p>\u003cp>结合原文脉络给出更贴切地例子\u003c/p>\u003cp>书中提到我们希望生命结束时，自己如何回顾以及别人如何悼念。我给出一个我的例子：我是John的学生，打我认识John那天开始，他就是我的人生导师。他热情，理性，充满智慧，并且在我需要的时候他总是可以来帮助到我，他总是愿意让我进入他的生活，让我看到他在为人父，为人夫，为人子，为人友，为人师方面所做的近乎完美的榜样。\u003cbr>\u003c/p>","interaction":"\u003cp>大家回想一下，在你过往的经历当中，有没有参加过一位对你有积极影响的人的葬礼或者追悼会等。当时你以及其他人是如何积极的评价和总结他的？比如一个一个称职的爸爸，成功的领导者？写下关键词。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>\u003cstrong>陈安博\u003c/strong>\u003c/p>\u003cp>㊋1985年生，在西藏佛学院安静的闭上了双眼，享年500岁，是世界上最长寿的人，前无古人后无来者的传奇人物\u003c/p>\u003cp>㊌出生在XX山沟沟，先居住在古都西安，后定居香港、北京，又移居上海、台湾、新加坡、洛杉矶、尼斯、太空等地。游历世界每个角落，是个名副其实的旅居家，每到一处在当地最静谧的地段置地一处，后来都标列为“安博故居”\u003c/p>\u003cp>㊍著作家，一生著作无数涵盖文化、艺术、科技等诸多领域，盛传不衰，是第777届诺贝尔文学奖获得者；同时也是位词曲家，曾为四大天王、八大金刚、十大天团作曲作词，歌曲朗朗上口，家喻户晓，老少皆可吟唱\u003c/p>\u003cp>㊏他也是为传奇的商人，涉及实业、金融、it、传媒关乎人类吃住行游购娱等所有行业，创立的企业及业务全球遍布。企业建立了一种全球独一无二的工作模式，为全员谋福祉，其公司的员工都是登上了世界富豪排行榜并居前列。一生家财万贯，乐善好施，救济助者数计，建设安博学校、安博福利院遍布世界各地免费开放，为全球的教育、环保、慈善、儿童、妇女、老人弱势群体等诸多事业做出了卓越奉献，是连续第888届诺贝尔和平奖获得者，几乎获得诺贝尔所有奖项\u003c/p>\u003cp>一生名正言顺结发夫妻十个，子女无数，但他最爱的还是他的首任和子女\u003c/p>\u003cp>㊐他还是一位牛逼大王，一生吹牛无数，年轻时曾吹过的牛后来都一一实现了\u003c/p>\u003cp>㊊他的所有称号前面都必须加上“伟大的”“著名的”字号\u003c/p>\u003cp>㊤他离世的时候全球集体熄灯1小时，全球各国降半旗，宇宙公民集体为其默哀，并把每年的某月某日定为其纪念日；所有国家的最大面额的钱币上是他的图像……\u003c/p>\u003cp>还远不止这些，罄竹难书（这定是个褒义词）啊\u003c/p>\u003cp>其实他生前是个默默无闻的人，他告诫后人死后在他的墓碑前立块无字碑即可，上面的这些介绍都是后人给他的写的\u003c/p>\u003cp>真是无字碑头镌字满\u003c/p>\u003cp>(如下A3是另加的，以便于大家能更好地进入基于角色的人生目标的设定)\u003c/p>\u003cp>接下来趁热打铁，请大家编一个故事，想象一下，数十年之后，你自己的某个亲人，朋友或者其他角色，去参加你的葬礼，他在葬礼上要致辞，你来从他的角度致辞。这个故事要求，开场表示你的身份，描述这个身份和你之间的故事，由此你看到他的的优秀品质和闪光点。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>我是汤老师的朋友。此人生前比较倔强，刚开始做了一些让自己后悔的事情，后来还是很成功的。没事喜欢捣腾一些事情，爱思考自己捣腾的事情，有时候会乐观去想，有时候悲观去想，最后会挺矛盾的。最后自己会朝着乐观的方向走，平时爱聊自己的理想，会因为一些事情而改变自己的人生态度，愿意为自己的目标奋斗。别人在读书的时候，他在读书；别人毕业了，他还在读书。等别人毕业的时候，他又在读书的时候开始了工作，开始创业。是一个时而慢时而快不够规律的挺矛盾的人。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4872,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 每个人在生命中都扮演着不同的角色，随着年龄的增长，角色也在增加。小时候我们扮演的角色很少，压力自然也小。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 时常不自知的是，我们经常只记得年龄的增长，却忘记了角色在增加。有时候太过专注于一个角色，却忘记了这个舞台还有太多的角色等待着我们。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 因此，确定了自己的人生方向后，还要把它具体化为人生目标，才能让我们追求的生命的意义真正落地。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 人生目标的确定可以说是一门绝对的技术活。既要能仰望星空，又得脚踏实地。在尝试过不同的计划、目标制定方法后，我发现用史蒂芬.柯维在《高效能认识的七个习惯》中提到的角色定位的方法来确认人生目标最方便，最有效。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;每个人都在生活中承担着不同的角色，我们需要在不同的角色里确认各自的目标，让这个目标贴合我们人生的愿景。这样我们既能保证人生中重要的事都有个可以信赖的方向，也能保证人生不会因为过于集中某一两件事情而失去平衡，反受其害。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 从今天开始，列一份角色与目标的清单，每天、每周、每个月回顾一下，不将目光只局限于一点，而是宏观考量自己的各种角色和定位，并时时自我修正。\u003cbr> 你的人生将变得不同。\u003c/p>","explains":"\u003ch1>自测\u003c/h1>\u003cp>请大家根据自己的情况勾选自测表，（1表示很不符合，6表示非常符合）\u003cbr> 1.我非常明确自己想做和自己能做的事情\u003cbr> 2.我有清晰的，写下来的人生目标\u003cbr> 3.我会定期回顾修正人生目标\u003cbr> 4.我现在做的每一件事情都是朝着人生目标方向的\u003cbr> 5.当我做任何重要决定时，我都会参考我的人生目标\u003c/p>\u003ch2>\u003cem>自测解释\u003c/em>\u003c/h2>\u003cp>做这个自测表的目的，其实是想让大家自己回忆一下，是否能否清晰地清楚自己的人生方向，测测自己的迷茫指数，以使后面的拆解更能满足你的需求。\u003cbr>如果你的分数在20以上，说明你基本上有比较明确的人生目标的，如果你是16以下，那说明你来对了：）\u003c/p>\u003ch3>互动\u003c/h3>\u003cp>读完片段后，大家觉得这段有什么关键词？或者对你触动比较大的地方？\u003c/p>\u003ch3>why\u003c/h3>\u003cp>我们困惑为什么小时候无忧无虑，可随着年龄的增加，压力越来越大。比如：小时候努力学习就能被表扬，但现在单单努力工作已经无法满足了，照样还会被爸妈，爱人埋怨等等。原因很简单，我们的角色增加了，而我们往往太过于专注于一个角色，而忽略了其他更重要的角色，从而使得我们的生活失去平衡。\u003c/p>\u003cp>\u003cstrong>不这么做的坏处\u003c/strong>\u003c/p>\u003cp>当我们没有为生命规划明确的目标时，我们会面临一系列重大问题，比如我们可能在家庭生活中毫无幸福，工作没有成就感，自己和他人对自己的评价也趋于负面或者平庸。。。\u003c/p>\u003ch3>what（包括举例）\u003c/h3>\u003cp>人生目标既要仰望星空又要脚踏实地。\u003c/p>\u003cp>仰望星空就是要让自己有所期许，我们的目标必须让自己羡慕，想想都觉得美。\u003c/p>\u003cp>\u003cstrong>结合原文脉络给出更贴切的例子\u003c/strong>：比如为家人提供基本衣食住行的供给就不够仰望星空，而作为爸爸，在爱和勇敢追求梦想方面为孩子做榜样就拔高了许多。\u003c/p>\u003cp>脚踏实地是让自己能力及行动，不要觉得好像没地方下脚，不知怎么开始。\u003c/p>\u003cp>\u003cstrong>结合原文脉络给出更贴切的例子\u003c/strong>：比如我要实现中华名族的伟大复兴就不够脚踏实地，而在公民角色上，尽心履行宪法赋予我的职责就更靠谱一点。\u003c/p>\u003ch3>how细化心动步骤\u003c/h3>\u003cp>1，列出你在生活中承担着的角色\u003c/p>\u003cp>2，将角色按照重要程度排序\u003c/p>\u003cp>3，通过采取角色定位法，可以将自己生活中的重要角色都设定目标。\u003c/p>\u003cp>4，定期回顾修正（\u003cem>一次制定完成后，一定不会很完整全面，另一方面很快就会忘记，所以要定期回顾修正。\u003c/em>\u003cem>）\u003c/em>\u003cbr>\u003c/p>","interaction":"\u003ch2>\u003cem>A3\u003c/em>\u003cem>现场演练\u003c/em>\u003c/h2>\u003cp>1，写下你在你的生命中所扮演的角色，越多越好，不要停。\u003c/p>\u003cp>2，认真思考你所最看重的3-5个角色，你可以用打分的方式，10分最高，1分最低，给每一个角色打分，然后挑出最高的几个。\u003c/p>\u003cp>3，根据刚才的拆解按照书中的方法，给每个角色设定目标。这个目标就是我们百年之后，该角色所对应的人在我们追悼会上的陈述。\u003c/p>\u003cp>4，然后标注一个合理的日期进行回顾修正。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>女儿：希望可以给父母带来安慰和依靠，我需要去更多关注他们，了解他们地需要，给他们更多地陪伴。\u003c/p>\u003cp>老师：给我的学生循序渐进地教育模式，帮助他们对艺术产生兴趣，去体会艺术，将来从事艺术类地职业或者是艺术家。\u003c/p>\u003cp>队友：希望成为团队中不可或缺地一员，与大家一起做1+1&gt;2的事情，同时带来比较大的凝聚力。\u003c/p>\u003cp>下属：跟大家一起脚踏实地的做事情。\u003cbr>\u003c/p>\u003cp>学生：在专业上面有自己的表达和突破，在产品设计这一块有自己的\u003c/p>\u003ch2>\u003cem>A3\u003c/em>\u003cem>现场角色扮演\u003c/em>\u003c/h2>\u003cp>两两分组，结对演练。\u003c/p>\u003cp>每人快速分享一下最重要的三个角色（现场包括孩子，父母，下属）\u003c/p>\u003cp>角色是孩子，场景是父母催婚；\u003cbr> 角色是父母，场景是与自己的父母关于育儿产生了不同的看法，沟通中。\u003cbr>角色是下属，场景领导无端指责自己。\u003cbr> 请思考根据你的角色定位，你要现场如何应对以上的场景以及后续处理？两个人一起编个剧。\u003c/p>\u003cp>最后请一位搭档总结过程以及他的感受。\u003c/p>\u003cp>案例：\u003c/p>\u003cp>孩子：为什么要逼我结婚呢？\u003c/p>\u003cp>妈妈：过了年你都25岁了。\u003c/p>\u003cp>孩子：才25岁嘛。\u003c/p>\u003cp>妈妈：25岁已经是晚婚了，再不结婚都老了。\u003c/p>\u003cp>孩子：男孩子嘛，要事业为重。\u003c/p>\u003cp>妈妈：这不影响的嘛，先成家就可以安心地好好追求你的事业了呀。而且还可以有人照顾你的衣食起居。你想我们这么远也没办法照顾你，找个人可以照顾你多好。\u003c/p>\u003cp>孩子：不是不想找，只是现在挺忙的。\u003c/p>\u003cp>妈妈：你们年轻人总是说忙，谁都是这么过来的，这个不耽误的呀。你现在工作稳定，上海机会也蛮多的。而且我知道上海美女挺多的，你不能那么挑知道吗？\u003c/p>\u003cp>孩子：主要是没时间。\u003c/p>\u003cp>妈妈：不可能，你骗我。\u003c/p>\u003cp>孩子：难道你不觉得可能人类的这个婚姻制度本身就是有问题的吗？为什么两个不相干的人一定要最后绑在一起呢。\u003cbr>\u003c/p>\u003cp>妈妈：难道你不想结婚？什么时候有这个想法的？你不想要孩子了？你这个不孝子，你不知道不孝有三，无后为大吗？你不为自己考虑也需要为家人考虑。\u003c/p>\u003cp>孩子：一个人挺好的呀。\u003c/p>\u003cp>。。。\u003c/p>\u003cp>搭档分享感受：\u003c/p>\u003cp>儿子说有女友还没毕业，妈妈要求五一带回来看看，儿子说好的。这个儿子还是蛮乖的。\u003c/p>\u003cp>儿子挺反对的，两代人的冲突，觉得老一辈思想out了。妈妈会分享传统的思想。（儿子后来觉得这样的沟通还是可是有改进的，结合自己的定位。）\u003c/p>\u003ch2>\u003cem>A2\u003c/em>\u003c/h2>\u003cp>结合一两个最重要的角色，规划下周要做到什么？\u003c/p>\u003cp>2-3年要做到什么？\u003c/p>\u003cp>5-10要做到什么？\u003c/p>\u003cp>案例：\u003c/p>\u003cp>本周：\u003c/p>\u003cp>女友：多健身，\u003c/p>\u003cp>HR：看书，多与人讨论HR的经验\u003c/p>\u003cp>2-3年:\u003c/p>\u003cp>女友：可能会有孩子，身材要继续保持运动锻炼\u003c/p>\u003cp>HR：希望有向上发展的通道，提升自己的专业能力\u003c/p>\u003cp>5-10年：\u003c/p>\u003cp>妻子：多才多艺，善解人意。\u003c/p>\u003cp>HR：职级往上的突破，在管理上与自己的一套方法论，在专业和工资这一块也有所提升。\u003c/p>\u003ch2>\u003cem>结语\u003c/em>\u003c/h2>\u003cp>通过今天的拆解，是不是都对自己的人生方向明了一点了呢？通过短短一个小时，肯定是不够的，希望大家今天回去后继续不断地完善，并且定期修正，让自己的人生减少一点迷茫，增加一点光彩。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1490148038000,"updated_at":1490148038000,"ria":true},{"id":2091,"topic":"34枚硬币时间记录法","learn_goal":"通过记录时间消费来审视我们的人生","remark":"    你是否曾有过这样的经历，在假期前写下这样的时间计划：\r\n        6点起床，7点晨跑，8点到9点读英语，9点到11点写文章……\r\n        你是否曾因为没有完成自己的时间表而感受挫败和焦虑？\r\n        是的，人生就是时间，人活着就是因为在这个世界上存在过几十年的时间。\r\n        牛人都是时间管理的高手，不过大部分人会犯一个错误，说到时间管理就会想到各种各样的制定的时间计划，任务清单……\r\n        新东方最年轻的集团演讲师，50万册畅销书作者艾力告诉我们：如果你不知道自己的时间是花费在了哪里，又怎么能去确定未来的时间会用得更好呢？\r\n","level":"TF1-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"羽美人","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"你是否曾有过这样的经历，在假期前写下这样的时间计划：\r\n 6点起床，7点晨跑，8点到9点读英语，9点到11点写文章……\r\n 你是否曾因为没有完成自己的时间表而感受挫败和焦虑？\r\n 是的，人生就是时间，人活着就是因为在这个世界上存在过几十年的时间。\r\n 牛人都是时间管理的高手，不过大部分人会犯一个错误，说到时间管理就会想到各种各样的制定的时间计划，任务清单……\r\n 新东方最年轻的集团演讲师，50万册畅销书作者艾力告诉我们：如果你不知道自己的时间是花费在了哪里，又怎么能去确定未来的时间会用得更好呢？\r\n 周日来南京东路，听羽美人带拆《你一年的8760小时》...","ratings_count":0,"texts":[{"id":4729,"quote":"\u003cp>牛人都是时间管理的高手。不过大部分人会犯一个错误，一说到时间管理就想到各种各样的时间计划，定各种雄心勃勃的目标。\u003c/p>\u003cp>订计划是时间管理的一部分，但不是最重要的一部分。如果直接通过订计划来改善时间管理，就好比去医院不诊断直接开药。你都不知道你过去的时间是如何浪费的，怎么能去确定未来的时间会用得更好呢？\u003c/p>\u003cp>因此，比起管理，时间记录或许更有效。\u003c/p>\u003cp>用34枚金币时间管理法，时间就能像账单一样被记得很清楚。\u003c/p>\u003cp>原理很简单：早上7点起床，晚上12点睡觉，17个醒着的小时，按半小时划分，将时间分为34份，就有了34枚金币。\u003c/p>\u003cp>每天晚上，数一下金币是怎么花的，就有了一个非常不错的收获，你会发现，一天的时间，干了什么，高效与否，一目了然。这也就是我一年能做那么多事的最重要的原因。\u003c/p>\u003cp>有人会问：为什么是7点起床，不能8点起床？可以，那就是32枚金币。9点起床可不可以？那就是30枚金币\u003c/p>\u003cp>以半小时为单位来记录的原因是，半小时是我们大部分人完成一部分工作的时间，半小时足够了。或者说，你要完成4小时的工作，半小时是你做好准备进入这个工作的时间。\u003c/p>","explains":"\u003cp>这是“34枚金币时间管理法”这一章中的一个片段，这个片主要讲了一个什么观点呢？大家有没有看到一个关键句？对。\u003c/p>\u003cp>因此，比起管理，时间记录或许更有效。\u003c/p>\u003cp>这句话谈到了作者一个非常重要的观点，就是大部分人会认为时间管理最重要的就是做时间计划表，然后倒逼自己，从年计划，到月计划，到周计划，到日计划。\u003c/p>\u003cp>但作者在这里谈到，时间纪录才是时间管理最重要的一部分。如果我们不知道自己每天的时间都花费在了哪些地方，我们怎么能够对症下药，去把浪费的地方填补上呢？作者举了一个例子：直接通过订计划来改善时间管理，是粗放型的，就好比我们去医院看病，不诊断病因而直接开药，至多也是粗略诊断一下就开药，那开的药很可能是无效的。\u003c/p>\u003cp>所以时间记录是时间管理的第一步。这个片段下半截，给出了“34枚金币时间管理法”中一个时间记录的方法。\u003c/p>\u003cp>一个人早上7点起床，晚上12点睡觉，有17个小时是醒着的，按半小时划分，将时间分为34份，就有了34枚金币。当然，作者也谈到，这个34枚金币可以根据自己的作息调整成32枚金币，30枚金币。这个不重要，重要的是，如果我们记录了这34枚金币花在了什么地方，那么每天晚上，数一下金币是怎么花的，就有了一个清晰的诊断。我们的时间花在了哪些地方？哪些是必须要花费的时间，比如吃饭上厕所，哪些是不必要的浪费，哪些事情做的高效，哪些低效，一目了然。接下来才可以对症下药。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>大家平时会有记录时间花费这个习惯吗？或者说，大家有时间计划表完不成的情况出现吗？\u003c/p>\u003cp>我就讲一个我自己的例子吧，我是一个很热衷做时间计划的人。比如，我今年1月1号定了2017年上半年计划，里面写道：每周写2-3篇简书文章，把自己学到的一些实用类的方法和实践分享出来；每周锻炼1-2次；每周读1-2本书；参加拆书帮，8月底成为三级拆书家……等等。\u003c/p>\u003cp>这些计划我都按照smart原则制定得很具体的，还用了倒逼的方法去具体到每天几点到几点做什么，几点到几点做什么。我觉得自己这个计划很完美，天衣无缝，没什么问题。\u003c/p>\u003cp>可是结果是什么呢，通常都是周一的一部分计划没完成，累加到周二，这样周二的计划更加难以完成，累加到周三，最后到了周末，基本上有一半的计划是没有完成的，于是我加班加点熬夜，结果搞得自己身体疲惫，心情也常常很烦躁。\u003c/p>\u003cp>那每次失败了我都会自责，会觉得郁闷失落，我也会回头去思考为什么昨天，前天或者上周的时间计划失败了，但每次我去回忆的时候，都是一个模糊的概念，比如我可能预计1个小时完成的工作做了3个小时，我在路上花的时间比我想象的多，手机上的朋友突然找我，我每天很多时间是在处理他们的事情，我多跑了几趟厕所……等等，因为模糊，最后我自己总结成一句话，没有意志力，没有自控力，效率不高。\u003c/p>\u003cp>可是，即使我学习了意志力管理，自控力管理，习惯养成，克服拖延症等等，我发现仍然完成不了计划。\u003c/p>\u003cp>所以，当我看到这本书以及其他时间管理书中都谈到：“记录时间花费是时间管理的第一步”，我突然明白了一件事，光开药，下猛药是不够的，我首先要诊断出病因在哪里，这个病因要具体详细，而且是经常会犯的，也就是要从记录中找到我经常习惯性浪费时间在哪些方面，是个什么模式，这样才能对症下药，而非一味地下猛药。医生病人都很辛苦，却对病情没有帮助。\u003c/p>\u003cp>&nbsp;\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>所以呢，接下来我要怎么做呢。作者在书中介绍了有一个“34枚金币时间管理法”的APP。我昨天下载来试用了一下，它有几个特色。（打开手机展示）\u003c/p>\u003cp>第1，它已经把一天时间划分为34块，所以我只需要在里面填内容就可以了。\u003c/p>\u003cp>第2，它将我们所有的时间花费都设定在了五个方面里（尽兴娱乐、休息放松、高效工作、强迫工作，无效拖延），所以当我记录下每块金币用在了哪里，并把它放进五个方面中的一个，它会自动形成饼图，就跟账单一样一目了然，无需自己去统计和整理。\u003c/p>\u003cp>我的下一步行动就是按照这个时间记录的方法，先记录我下一周的时间花费，然后在根据统计数据图表，找到自己时间浪费的问题所在，写一个诊断书，之后我再针对性的去解决。\u003c/p>\u003cp>作者也谈到，不是说一定要每半个小时停下来记录一下。所以我如果能够用番茄钟半小时提醒我一下，那很好，如果不行，可以每天晚上花15分钟认真回想并记录。\u003c/p>\u003cp>最后，我就用作者的一句话作结：生活如果没有记录，就好像生活不曾发生过一样。苏格拉底说：“不经过检视的人生是不值得活的。”一个人应该知道自己做了些什么，应该了解自己，而时间记录会帮助我们检视自己的人生。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488851600000,"updated_at":1488852048000,"ria":true},{"id":1000,"topic":"寻找自己的人生目标","learn_goal":"通过角色定位，找到自己的人生目标","remark":"","level":"TF3-3","duration":50,"status":0,"type":0,"chaishujia":{"username":"莫妮卡","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"不知道大家会不会有这样的情景，每天都很忙碌，在公司一天跑东跑西，回家到处收拾，日子过的很紧凑，却不觉得充实，每天都在努力，却不知道自己的努力朝向何方。作为老公，家里的顶梁柱，努力工作，天天加班，忽略了家人，忽略了自己健康，自己很辛苦，别人却也不领情，如果你也有这样的场景，那通过今天这两个片段的学习，希望能帮助大家找回些许方向。这本书的作者是艾力，曾经是参加过超级演说家，奇葩说，是理性与自律的化身，他创造了34枚金币的时间管理方法，影响了一大批人，是时间管理初级入门的一本好书。而且作者阅读了大量的致用类书籍，并使用很多经典著作的方法论，进行实践，并把自己的实践经验写作书中，推荐大家都来阅读一下。","ratings_count":0,"texts":[{"id":3153,"quote":"\u003cp>&nbsp; 不要停下来，你还在葬礼中，一个会在五十、六十、甚至是一百年后真实发生的葬礼。从古至今，一个人自出生那刻起，便是向死而生，任何一个人都不能逃离死亡的命运。\u003c/p>\u003cp>我们希望在生命结束时，如何回顾自己一生的得失？又希望别人在我们的葬礼如何悼念自己？\u003c/p>\u003cp>&nbsp; 每个人终将离开这个世界，在我看来，生命的意义蕴与当下的每一个时刻和每个选择中。假设明天是你的生命的最后一天，你是否还选择做你当下从事的事情？是否能坦然离开这个世界。\u003c/p>","explains":"\u003cp>&nbsp; 大家看到这个片段什么感触？\u003c/p>\u003cp>学习者1：通过小伙伴的情景带入，吓了自己一跳，但是立马有种慌乱的感觉\u003c/p>\u003cp>学习者2：觉得自己今天过得有点迷茫，不进取\u003c/p>\u003cp>学习者3：一直在思考怎么才能过的不迷茫。\u003c/p>\u003col>\u003cli>\u003cp>请大家根据自己的情况勾选自测表，（1表示很不符合，6表示非常符合）\u003c/p>\u003cp>1.我闭上眼睛就能想象出自己想要的人生方向\u003c/p>\u003cp>2.我有清晰的，写下来的人生目标\u003c/p>\u003cp>3.我会定期检视自己写下的人生目标\u003c/p>\u003cp>4.我现在做的事情80%以上都是朝着人生目标走的\u003c/p>\u003cp>5.当我对某件决定犹豫不决时，我会参考我的人生目标\u003cbr>\u003c/p>\u003c/li>\u003c/ol>\u003cp>&nbsp; 做这个自测表的目的，其实是想让大家自己回忆一下，是否能否清晰的清楚自己的人生方向，测测自己的迷茫指数，以使后面的拆解更能满足你的需求。\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;这个片段非常简单：主要介绍了这么几点，一，这是国外流行的墓园测试法，通过这个小场景的设定，能够给自己敲响警钟。二，人生很宏大，但是评价人生无非是两个方面，你自己怎么评价你的一生，你希望别人怎么评价你的一生。三，我们每时每刻做的事情，决定，都将或多或少的影响自己的人生目标，或前进或后退。就像刚才我问大家，今天你来拆书的目标是什么，与你的人生目标是相悖的还是同向的。四.另一方面，有效地梳理自己的人生方向有助于帮助自己做好更多的人生选择。当我们遇到重大决定时可以通过与人生目标相比较作出理性的决定。人生方向这个命题很大，突然问起，估计很少能有人迅速全面的回答出来，可是通过这样一种方法，可以引发我们的思考，促使自己更好的明确。\u003c/p>","interaction":"\u003cp>&nbsp; 拆解完这个片段，大家回想一下，如果生命就要终结，你希望大家怎么评价你？希望大家说你有什么品质，事迹？你希望一个称职的母亲，成功的领导者？是不是还是无法回答，没关系，我这里有个小窍门，大家可以尝试一下，请写下一个对你有积极影响的人。他的品质是什么。\u003c/p>\u003cp>学习者1：我的现任老板，\u003c/p>\u003cp>原因：1、是白手起家的成功女士。\u003c/p>\u003cp>&nbsp; &nbsp; 2、五十多岁了依然每天细高跟，妆容优雅。\u003c/p>\u003cp>&nbsp; &nbsp; 3、无论何时都保持理性，语气温柔和善。\u003c/p>\u003cp>&nbsp; &nbsp; 4、即使这个年纪每天都坚持4点起床读书。\u003c/p>\u003cp>&nbsp; &nbsp; 5、出差白天开会一天，晚上做ppt做到凌晨，第二天依然优雅滴出现在台上。\u003c/p>\u003cp>&nbsp; &nbsp; 6、遇到任何阻力，总是相信自己一定能解决问题。我一定要……是口头禅。\u003c/p>\u003cp>学习者2：圣经中的约翰\u003c/p>\u003cp>原因：1.虔诚的为众生布道\u003c/p>\u003cp>&nbsp; &nbsp; 2.不论遇到怎样的挫折，忠于自己心中的理想\u003c/p>\u003cp>&nbsp; &nbsp; 3.对大众仁慈，真正做到了别人打我左脸，我伸出右脸给他打\u003c/p>\u003cp>学习者3：胡歌\u003c/p>\u003cp>原因：1.坚韧，即使遭遇不幸，仍然勇敢的站在舞台上\u003c/p>\u003cp>&nbsp; &nbsp; 2.知道自己想要什么，当容貌大变后，便转变方向实现自己的梦想\u003c/p>\u003cp>&nbsp; &nbsp; 3.抗压能力，跌倒后勇敢的站起来，抵住压力从偶像派变成实力派\u003c/p>\u003cp>&nbsp; 大家很棒，现在是不是对你的人生方向有些眉目了？接下来趁热打铁，请大家编一个故事，想象一下，五十年，六十年之后，你自己的某个亲人，朋友或者其他角色，去参加你的葬礼，他在葬礼上要致辞，你来从他的角度致辞。这个故事要求，开场表示你的身份，描述这个身份和你之间的故事，由此你看到的她的品质或闪光点。\u003c/p>\u003cp>栗子：我是老莫的粉丝，一直以来老莫都是我的人生导师，她热情，善良，理性，充满智慧总是愿意抽出时间来帮助我们，提携后辈。而且她一直以来都这么美丽优雅。她的人生非常精彩，一直爱着她的爱人，孩子，家人，朋友，把自己也打理的井井有条，我希望我的人生也能向他这么精彩。\u003c/p>\u003cp>学习者1：首先感谢大家给我这个机会表达对张总的钦慕，我是个张总底下一个不起眼的小兵，她，是一个平凡但是坚韧不拔的女人，外表柔弱，内心强大。她温柔善良、外柔内刚。有包容一切的胸怀，有超前的高瞻远瞩，有宏大的格局，她为汽车后市场打造出世界闻名的xxx中国品牌；她创建了新的营销理念和品牌理念，是中国的品牌营销专家之一。虽然我从未正面接触过张总，但是每当我看到她意气风发的背影，便对前方的路更加明了。\u003c/p>\u003cp>学习者2：沉痛哀悼我的好朋友grace. 作为多年的好友，我们一同经历了少年、中年以及老年，在我心中她是一位优秀的人，不论在工作、家庭、社会贡献等方面，她都一直在努力尝试做得更好，并且她也最终做到了。工作上，她是一位有丰富经验的行业领袖，同时她也自己创造了一个家族小企业，并利用各种渠道运营得很好，她鼓励自己的孩子从小在公司里耳濡目染，自主观察、思考并发表意见，她培养各种具有上进心且有良知心的下属，她乐于与各种类型的人交朋友并讨论生活的各种经验，传播各种正能量。她宽容大度并乐观向上，她主动学习并乐于分享，她是一位终身学习者，一位严格自律者、她是我们大家的职业偶像。家庭上，她孝敬父母，支持先生，培养孩子。她每年家庭旅行，生活物质及时补给，营养健康充分保障。她了解每一个家庭成员的喜好与心愿，她努力做到倾听与理解，她提前在日历做好标注会尽可能去满足大家。她努力学习夫妻之道、亲子关系，她勤于思考并热衷应用，她会尝试用科学的方法去激发每个人的潜力，让每个人都可以做得更好。她是贤妻良母，更是良师益友、精神伙伴。她和孩子更多的是以朋友的身份相处，没有隔阂没有坚冰，孩子会尊重她感恩她，长大后会努力回报她。社会角色上，她重视每一种真诚的关系，她了解朋友的生活，知道朋友的难处理解朋友的缺点，她会主动并积极地去维护每一个生命中的好朋友。定期交流联系，分享观点意见，共同成长进步。她有信仰追求，真善美是她的原则，她积极付出和贡献，利用自己的知识储备和资源去帮助社会上每一个需要帮助的人。她定期去福利院做义工，她积极救助流浪动物，她为社会问题思考并努力改进，她尊重中国传统文化和经典传承，她热爱古诗词、曲艺、戏剧、舞蹈、乐器，她的生活丰富多彩、充实积极，她重视健康热爱运动，她勤于保养、注重健康，她坚持写作、学习外语，她喜欢旅游，将足迹撒遍世界各地，她是一位极有魅力的女性，是她孩子的偶像，是她老公的骄傲，更是她儿媳妇的榜样。以此纪念，一位优秀的女人走过的一生。感激此生有你来过。安息！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3154,"quote":"\u003cp>&nbsp; 每个人在生命中都扮演着不同的角色，随着年龄的增长，角色也在增加。小时候我们扮演的角色很少，压力自然也小。\u003c/p>\u003cp>&nbsp; 时常不自知的是，我们经常只记得年龄的增长，却忘记了角色在增加。有时候太过专注于一个角色，却忘记了这个舞台还有太多的角色等待着我们。\u003c/p>\u003cp>&nbsp; 因此，确定了自己的人生方向后，还要把它具体化为人生目标，才能让我们追求的生命的意义真正落地。\u003c/p>\u003cp>&nbsp; 人生目标的确定可以说是一门绝对的技术活。既要能仰望星空，又得脚踏实地。在尝试过不同的计划、目标制定方法后，我发现用史蒂芬.柯维在《高效能认识的七个习惯》中提到的角色定位的方法来确认人生目标最方便，最有效。\u003c/p>\u003cp>&nbsp; 每个人都在生活中承担着不同的角色，我们需要在不同的角色里确认各自的目标，让这个目标贴合我们人生的愿景。这样我们既能保证人生中重要的事都有个可以信赖的方向，也能保证人生不会因为过于集中某一两件事情而失去平衡，反受其害。\u003c/p>\u003cp>&nbsp; 从今天开始，列一份角色与目标的清单，每天、每周、每个月回顾一下，不将目光只局限于一点，而是宏观考量自己的各种角色和定位，并时时自我修正。\u003c/p>\u003cp>你的人生将变得不同。\u003c/p>","explains":"\u003cp>读完片段后，大家觉得这段有什么关键词？或者对你触动比较大的地方？\u003c/p>\u003cp>学习者1：人生目标要逐星踏石\u003c/p>\u003cp>学习者2：我们有时候太专注某个角色，没达到平衡\u003c/p>\u003cp>学习者3：通过每个月回顾检视才能有效果\u003c/p>\u003cp>大家很棒，我来总结一下\u003c/p>\u003cp>1.很多人都有这样的困惑，小时候无忧无虑，多开心，随着年龄的增加，压力越来越大。小时候努力学习就能被表扬，但现在单单努力工作已经无法满足了，照样还会被爸妈，老公埋怨，不能陪自己拉，不做家务拉，等等。\u003c/p>\u003cp>2.人生目标既要仰望星空又要脚踏实地。要让自己有所期许。让自己期许是我们的目标必须让自己羡慕，想想都觉得美，脚踏实地是让自己能力及行动，不要觉得好像没地方下脚，不知怎么开始。\u003c/p>\u003cp>3.通过采取角色定位法，可以将自己生活中的所有角色都设定目标，进而使生活达到平衡4.检视，一次制定完成后，并不能解决所有的问题，一方面会有遗漏，另一方面很快就会忘记，所以要定期检视。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;1.根据刚才的拆解按照书中的方法，我们来写下生活中所有的角色，并给每个角色设定目标，然后在自己的日程表上设定一个合理的日期进行检视。\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>妈妈：做个好妈妈，为宝宝竖立第一个人生楷模。从习惯到为人。每天至少一个小时陪宝宝。每天讲一个故事。每晚睡觉前抱宝宝。早上问候宝宝“美好的一天开始了”每周至少送宝贝上学一次。为宝宝建立时间管理表格，并以礼物作为每周奖品。保持干净整洁优雅，说话语气温柔和善。以身作则示范优秀。\u003c/p>\u003cp>朋友：做个真诚的朋友；每两周给好朋友电话一次。给朋友关心。\u003c/p>\u003cp>妻子：作个善解人意的优雅的妻子。整理房间，帮老公做家务，学会做饭。\u003c/p>\u003cp>女儿：孝敬爸妈公婆，不给公婆吵架，尊重公婆，定期给公婆送礼物；\u003c/p>\u003cp>妹妹：做个懂事的妹妹，每周给姐姐、哥哥电话问候。\u003c/p>\u003cp>员工：做一个有优秀的员工，努力做好每一天的工作。能够分享知识给大家。发现每个同事的优点，学习英式女人的优雅与教养；\u003c/p>\u003cp>学习者2：\u003c/p>\u003cp>丈夫：爱护者，不因妻子的脾气过失而吝啬爱，营造家庭的温馨气氛；倾听者：用注视的眼光陪伴妻子。保护者：在自己家人一方维护妻子；带领者：用实际行动引导妻子。\u003c/p>\u003cp>父亲：爱护者（特别对女儿）；玩伴；榜样；牧师\u003c/p>\u003cp>儿子：改变家庭的氛围，姐弟间的和平使者\u003c/p>\u003cp>下属：热爱工作，积极领会，坚决执行，保持敬畏\u003c/p>\u003cp>同事：有合作，有虚心，有思想，肯学习\u003c/p>\u003cp>领导：导师，教练。\u003c/p>\u003cp>&nbsp; 2.假设有这样的一个场景，有人（这个角色要你自己来决定）来上海旅游，想要住在你家里，前提，你家有地方住，但是你和你老公的生活会不方便，他还要求你陪玩。你答应还是不答应，根据你的角色定位，你要怎么处理？\u003c/p>\u003cp>学习者1：如果是父母，我会愉快的接受，并做好准备，因为我爱他们，这是我表达爱的一种方式；如果是朋友，我会问老公的意见，能否接受，不接受就拒绝；如果是老公的朋友，我会接受，因为我愿意牺牲一点不方便，让老公开心。\u003c/p>\u003cp>学习者2：任何人都不接受，因为我和老公是非常重视个人空间和家庭整洁度的，任何人的介入都会影响到我们。但是父母，关系好的我会在附件找旅馆接待他们，其他人直接告知，吃个饭可以，全程陪同没有时间和精力。\u003c/p>\u003cp>学习者3：虽然还没结婚，但是通过角色定位，我觉得我会接受双方父母来住，但期限不能超过两周，其他人会委婉拒绝，陪玩可以，来家住就算了。\u003c/p>\u003cp>&nbsp; &nbsp;大家太棒了，通过今天的拆解，是不是都对自己的人生方向明了一点了呢？通过短短的这个时间，肯定是不够的，希望大家今天回去后继续不断地完善，并且定期检视，让自己的人生减少一点迷茫，增加一点光彩，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475061271000,"updated_at":1475061271000,"ria":true},{"id":835,"topic":"逆向时间规划法","learn_goal":"利用逆向时间规划，做出合理的计划表","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"莫妮卡","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"不知道大家会不会有这样的情景，每天醒来，认真的翻开自己的笔记本，计划好今天的待办清单，看着自己劳逸结合的清单，觉得今天的生活应该过得轻松又充实，结果一天下来才发现，工作，学习任务没有按照预期的计划完成，甚至连安排好的娱乐活动也没享受到，感觉人生陷入了时间黑洞，时间到底去哪了呢？如果小伙伴们也遇到过这样的情况，那就可以通过阅读这本书来解答自己的问题了。这本书的作者是艾力，曾经是参加过超级演说家，奇葩说，是理性与自律的化身，他创造了34枚金币的时间管理方法，影响了一大批人，是时间管理初级入门的一本好书。推荐大家都来阅读一下。","ratings_count":0,"texts":[{"id":2596,"quote":"\u003cp>&nbsp; &nbsp;把所有的工作任务写在每一天的表格里，要开的会，要做的报告。最后加入自我提升时间，还有健身，约会。这个表格给人的感觉就是满满当当，累觉不爱。每天叫醒你的不是梦想，而是抽打自己的皮鞭。\u003cbr> 计划还是应该有的，但计划不能是人生的枷锁，而应该是生活的助力器。\u003cbr> 后来，我采用的计划时间的方法是：尼尔.菲奥先生在《战胜拖拉》中提及的逆向时间规划法，在每个周日拿出一段时间来，进行下周的规划。\u003cbr> 第一步，先记录下必须参加的活动，如会议、上课时间\u003cbr> 第二步，规划工作之前先把休闲娱乐、朋友聚餐等时间记录好\u003cbr> 第三步，自己读书，进修时间安排好\u003cbr> 第四步，把自己可以掌控的工作安排到余下的空闲时间里。\u003cbr> 这张表先会让你看到自己有充足的娱乐休闲时间，从而对这一周充满了期待。那么叫醒你的是梦想，而不再是责任。\u003cbr> \u003cbr> \u003c/p>","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;在开始今天的拆书前，首先请小伙伴们做个量表自测题。调查问卷 1.请大家根据自己的情况勾选自测表，（1表示很不符合，6表示非常符合）\u003c/p>\u003col>\u003cli>\u003cp>我每周都会做计划\u003c/p>\u003c/li>\u003cli>\u003cp>我能够按照计划表完成任务\u003c/p>\u003c/li>\u003cli>\u003cp>我的计划表让我觉得很压迫\u003c/p>\u003c/li>\u003cli>\u003cp>我曾经因为计划表太压迫而放弃做计划。\u003cbr>\u003c/p>\u003c/li>\u003c/ol>\u003cp>&nbsp;大家做完后，有什么感觉？觉得自己的计划能力怎么样？大部分人会有这样的困惑，如果不做计划，我想做的事情便一直提不上日程，但如果做了计划，发现自己没完成计划时，又觉得压迫。俗话说凡事预则立，不预则废，因此做计划还是有好处的，那怎么才能既获得做计划的好处，又能不受压迫呢。希望通过今天对这个拆页的学习，能给大家带来一些技能。\u003c/p>\u003cp>&nbsp; 看完这个片段，大家有触动的地方是什么？有没有小伙伴分享一两句话？在阅读这个片段前，大家是如何做计划的，看到这个片段你觉得跟之前的方式有什么不同？\u003cbr>\u003c/p>\u003cp>学习者A:我之前做计划从没考虑把娱乐时间也算进去\u003c/p>\u003cp>学习者B:之前做计划总是先把个人成长先写进去，最后在挤进很多不得不干的事情，所以很压迫\u003c/p>\u003cp>学习者C:朋友聚餐这样的休息时间也做计划，的确让人觉得很惬意\u003c/p>\u003cp>学习者D:这样做计划还能起到备忘的作用，不错\u003c/p>\u003cp>&nbsp; Ok，我来总结一下，这个片段非常简单：主要介绍了 1.大部分人都不会否定做计划的好处，但有时计划表被塞得满满登登时，又会觉得累觉不爱。比如大家看我微信群内分享的计划表，那是我之前参加100天行动时的计划表，满满登登，如果从学习的角度，真的是一份很完美的计划表，但是执行起来真的很累。感觉每天睁开眼就会有一堆的任务等着我去完成，真真的累觉不爱。\u003c/p>\u003cp>&nbsp; 计划表对自己的生活是有督促作用的，如何才能通过做计划的方式改变他的压迫效果呢？作者给了我们方法，那就是通过逆向时间规划的方式来制作计划表，具体如下\u003c/p>\u003cp>A:先将自己不得不做的事情加入计划表，比如预定的例行的周会，带宝宝打预防针，参加展览会等等，这样也能提前规划下自己的大体动向，也避免自己遗忘重要事项。\u003cbr> B:规划工作前先把玩的时间，想要参加的约会时间，添加到计划表，保证自己开心，有能量的去工作，为了激励自己，我们是不是还可以把这部分内容用彩笔标识，提醒自己原来每天用这么多时间玩。\u003cbr> C:把自己读书，进修，学习等的时间安排进去。\u003cbr> D:我自己可以掌控的工作安排一下，这样的话每天叫醒你的就不是皮鞭啦，而是更多的快乐。一场说走就走的旅行也扫不走生活的压力，而先保证自己的娱乐时间，时刻让自己知道下一刻就是我的娱乐时间。\u003c/p>","interaction":"\u003cp>&nbsp;看完这个片段，我们要怎么用呢？我们是不是可以学习借鉴时间倒推法，学习制定一套符合自己时间计划方法呢？ 俗话说实践出真知，只有用一下我们才知道好不好用，需要怎么改进，所以，请大家阅读下面的案例，帮助主人公设计下计划表，看看应该如何安排后面的行程才能不那么压迫？\u003c/p>\u003cp>&nbsp; A3你是某大公司的董事长秘书，董事长的大小事务都要你跟他一起协商安排，虽然工作很久了，但是董事长总是埋怨你给他安排的计划表太仓促，总让他觉得忙不完。他下周的需要做的事情如下，请大家讨论安排顺序并阐述相关原因：跟董事会开例会（每月固定时间一次），打高尔夫球，给员工讲话，陪自己的爱人，阅读战略管理类的书籍，飞往广州谈事情，去医院看牙。\u003c/p>\u003cp>学习者讨论结果：先将跟董事会开例会，去医院看牙，去广州出差，排在时间表内，因为这是固定的不能改变的，然后将午饭，打高尔夫球，陪伴爱人的时间，放入时间表，这是愉悦的休闲时间，可以让董事长休息下积攒能力，然后再把阅读时间安排进时间表，最后在插空决定什么时候给员工讲话。\u003c/p>\u003cp>&nbsp;A2大家非常棒，通过今天的拆解，应该懂得如何制定一份可行的行动计划了吧，现在要给大家一个小任务哦，请大家回去，按照今天学到的逆向时间规划法，规划自己下周的行程，并解释原因，抛到群里，大家相互监督执行哦。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1472647146000,"updated_at":1472647211000,"ria":true},{"id":775,"topic":"通过记录时间，了解自己，制定诱人的生活计划","learn_goal":"学习34枚金币时间管理法，制定轻松地生活计划","remark":"","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"莫妮卡","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"今天是定级考试，时间控制严格，当有伙伴偏离主题时，我会直接打断。另外我们不对作者的言论对错与否进行评论，仅仅从片段中汲取自己需要的知识，拿来加工一下，用在自己的生活中。就像农夫山泉的广告词，可以说我们更像是知识海洋的搬运工，把精华搬到自己的生活中去。\r\n 在开始今天的拆书前，首先请小伙伴们做个量表自测题。\r\n请大家根据自己的情况勾选自测表，（1表示很不符合，6表示非常符合）\r\n1.我清楚地记得我的年初计划\r\n2.我还在按部就班的逐步完成我的年初计划\r\n3.我清楚地记得我上周时间花费情况\r\n4.我能够清楚地记得我去年犯过的10个错误\r\n5.我能够清楚地记得我去年做过的最有意义的10件事情\r\n6.我能在规定的时间内完成计划的事情和工作","ratings_count":0,"texts":[{"id":2489,"quote":"\u003cp>&nbsp; 人生当然是个宏大的话题，但它却可以落实到一个相对具体的东西上，没错，人生就是时间，人活着就是因为在这个世界存在过几十年的时间。很多人年轻时自以为有大把的时间，就常常挥霍无度，年老时才知是日无多，才学会珍惜时间，却为时已晚。\u003cbr>大部分人会犯一个错误，一说到时间管理，就想到各种各样的时间计划，定各种雄心勃勃的目标。但有些时候，你下定决心要做某件事，最后微博微信什么的诱惑又让自己无法实现目标，非常痛苦。所以我说订计划是时间管理的一部分，但不是最重要的一部分。 如果直接通过订计划来改善时间管理，就好比去医院不诊断直接开药。你还不知道你过去的时间是如何浪费的，怎么能去确定未来的时间会用得更好呢？\u003cbr>因此，比起管理，时间记录或许更有效。\u003c/p>","explains":"\u003cp>&nbsp; 这个片段非常简单：首先作者认为，人生这个话题很宏大，就像我们经常看到的所谓鸡汤文章，其实都是在讲人生，看过之后雄心勃勃，但仍然不知从哪做起，所以，我们要从人生这个宏大的概念落实到一个具体的东西上，进行改变，从而见微知著。因此作者将人生落实的时间上，把握人生先从把握住时间开始。\u003cbr> &nbsp;大部分人会犯一个错误，一说到时间管理就想到时间计划，定各种雄心勃勃的目标。在这方面我曾经有过经验，我将我以前的计划表跑到群里，大家看下，这个计划表的制作历经十几次的改良，咨询了好几位大咖，用尽我的洪荒之力啊，大家看到这个满满登登的计划表是不是觉得我很牛，跟大家的感受相同，每次我看到这个计划表，对自己的崇拜就会增加几分，看这个计划遵循了SMRT原则，有愿景，有奖励，有频率，大表划分了时间，其他sheet中还细化时间点，几点起床，先做什么后做什么。计划本身非常棒，然而，所有的好故事都有然而，我也不例外，但是实施结果如何，几乎惨不忍睹，我忍痛坚持了2周，结果只有2天是完全完成的。为什么会出现这种情况，其实原因就在于，我还没有了解清楚自己的时间到底去了哪里，也不清楚自己完成某项工作到底需要花费多长时间，贸然的订立计划，就会造成完不成的现象，当完不成时，又会引起情绪连锁反应，产生挫败感。这个计划终止之后，我花了好久才回复元气。正如作者所说，你去看病，却还没诊断就开始开方子，当然是行不通的，只会治标不治本。因此在时间管理初始，我们要先通过记录时间来了解自己。\u003c/p>","interaction":"\u003cp>&nbsp; 以上是我们第一个片段的I，刚才我们也做了自测题，正如片段所说，人生太宏大，我们需要一些具体的东西来衡量，过不过的好人生，就要看看我们的人生目标实现的如何了，长期人生目标也太宏大，我们来看下自己的年内计划实现的如何就能评价，请大家回忆一下去年你想做的事情，请用三分钟时间分享三件目标，并粗略评估，到目前为止，进展如何。以供我们第二个片段使用。\u003c/p>\u003cp>学习者A:我的三件目标，学车，跑步，读书\u003c/p>\u003cp>学习者B:我的三件目标：建立个人品牌，写作，工作\u003c/p>\u003cp>学习者C:我的三件目标：成立工作室，练出人鱼线，成为拆书家\u003c/p>\u003cp>学习者D:我的三件目标：学手账，换工作，养成跑步习惯\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":2490,"quote":"\u003cp>&nbsp;&nbsp;时间这个东西很抽象，为了更重视时间的价值， 我采用把时间当金钱一样去记录的方法。\u003cbr>原理很简单：早上7点起床，晚上12点睡觉，17个醒着的小时，按照半小时划分，将时间分为34份，就有了34枚金币。每天晚上，数一下金币怎么花的，你就会发现，一天的时间，都干了什么，高效与否，一目了然。\u003cbr>记录完成后就要去分析，我把时间分为五类。第一类是尽情娱乐时间，第二类是休息时间，第三类是强迫工作时间，第四类是高效工作时间，第五类是拖延时间。\u003cbr>&nbsp;&nbsp;每一周我把自己高效工作的时间除以4，而把我拖延的时间除以2，之后用前面得到的数字减去后面得到的数字，即为我奖励自己，通过不断地高效工作，减少拖延时间，我就有奖励自己的时间了，这部分时间就用来做自己喜欢的事情，比如说去玩《魔兽世界》。\u003cbr>&nbsp;&nbsp;每周记录完成之后我都会进行—个反思，把每周做的有意义的傻的事情记下来。这些记录就会帮你有个非常直观的认识。 你就会知道自己每一天都有哪些收获，每一天都有哪些成长。它也会给你极大的成就感，从而提高自控力。\u003cbr>&nbsp;&nbsp;我过去的的一年，真的非常精彩，每个月的时间如何规划如何使用都有相关的记录，每一周，也有相关时间表格的统计、分析，有些时候浪费的时间多了一些，有些时候休息的时间少了一些，我也会相应地调整。\u003c/p>","explains":"\u003cp>&nbsp; 这个片段主要讲了以下几点：\u003c/p>\u003col>\u003cli>\u003cp>时间很抽象，要想记录时间，就要把它价值化，形象化。我们经常说，时间就是金钱，可是真正做到把时间当做金钱的人却很少。为什么比作金钱会好呢，第一好数好记，第二能够刺激到自己，买一件裙子花了多少钱，问你你立马能想起来，但问你花了多长时间是不是要想一会呢，再比如当我们想到昨天浑浑噩噩过去了一天的，好像没什么感觉，如果说昨天丢了1000元，是不是想想都觉得心疼？通过这个道理，作者就真的把时间具像成金钱，一方面呢便于统计，因为人数钱的能力肯定比数时间的能力强。当然这里作者将金钱想象成了金币，也许金币也不够刺激，你可以同等原理的把他们等同成人民币啊，更实在，更好数，还能清楚地知道能买到多少东西。比如我认为我每天8小时可以创造400元的价值，那每小时就值50块人民币。\u003c/p>\u003c/li>\u003cli>\u003cp>具体原理是这样的：人的一天有24h，作者将24h减去7小时的睡眠时间，又将剩余的17小时，每半小时当做一枚金币，每天记录自己34枚金币的花费情况。这样通过每天晚上回家数数金币，就知道自己一天干了什么了，这种感觉是不是很棒啊。什么时候记录呢？不必每半小时停下，这样有可能打断你当下的工作，作者地方法是每天晚上花半小时的时间回忆，如果回忆不起来，那就标记成浪费时间。因为人对自己高效工作的时间，约会的时间等还是印象深刻的。\u003c/p>\u003c/li>\u003cli>\u003cp>记录完成要干什么呢，分析时间，看看自己的时间到底去哪了，作者将自己的时间大体分类，作者根据自己的情况分成了5类，我们也可根据自己的情况分类，将自己的时间做成表格分析，从而更加清楚自己的时间花费在了什么地方。为什么要进行分类呢，因为你一天会做很多不同类型的事情，但是所做的事情都是围绕你的人生目标人生兴趣做的，通过分类，你就能清楚地看到你的偏重在哪里，是否偏离了你的目标。从而使自己的调整方向更为清晰。\u003c/p>\u003c/li>\u003cli>\u003cp>每周对自己的记录进行反思总结。反思自己犯同过哪些错误，以及反思自己每天都有哪些成长，哪些收获。看到错误就提醒自己下次不要再犯同样的错误，看到收获和成长，自己就会更有成就感，从而再接再励。\u003c/p>\u003c/li>\u003cli>\u003cp>设定规则奖励自己，当自己的时间统计表明，你很高效的利用时间时，设定规则奖励自己，人都需要有持续的利益刺激的。这种利益可以是享受时间的刺激，也可以是真正的金钱刺激，我的方法是当自己朝着自己方向的努力时间超过享受时间时，我就奖励自己差价金钱买礼物。\u003c/p>\u003c/li>\u003cli>\u003cp>当通过时间分析，发现自己的生活不太平衡时，那就调整一下以使其更加高效。\u003c/p>\u003c/li>\u003c/ol>","interaction":"\u003cp>&nbsp;看完这个片段，我们要怎么用呢？我们是不是可以学习借鉴艾力的金币法，制定一套符合自己时间管理方法呢？\u003cbr>&nbsp; 俗话说实践出真知，只有用一下我们才知道好不好用，需要怎么改进，所以，请大家按照自测表背面的表格回忆下自己前两天（周四周五）金币花费情况。在填写表格时请从早上睁开眼开始算起，每半小时一个金币，如果时间不够半小时，或超过，就通过大约估算的方式记录。如果你觉得半小时不适合你的统计，你也可以通过记录起止时间来完成，表格的最后分类不要填写。\u003c/p>\u003cp>&nbsp; 通过刚才的回忆，大家一天会有多少金币？ 每天的金币花的值得吗？\u003cbr>\u003c/p>\u003cp>觉得这个方法可以刺激到你吗？还是换成人民币更还一点？或者把时间在具体一点，1min一块钱? 半小时一个金币适合你吗？Ok，第二步，请小伙伴们参照自己表格统计中，表格记录的项目，将自己的时间大体分为五类，然后再分类表格内填上你的分类。大家简单思考一两分钟，然后在小组内讨论，大家完成了吗，请大家看一下你的五类时间中，为了完成你去年目标的时间有多少？请小伙伴在小组内讨论一下，并分析自己的时间都去哪了？讨论以下几个问题，\u003c/p>\u003cp>1.我通过时间记录把我的时间分为5类：（参考：高效工作；享受；被迫工作；休息；无意义时间）。\u003c/p>\u003cp>2.我的时间中，为实现去年某项目标的时间为。。。？是否需要调整？\u003cbr>（比如为实现三级拆书家，我过去两天花在拆书时间为4h，继续保持）\u003cbr>\u003c/p>\u003cp>3.制定规则奖励自己：（例：高效工作-0.5*享受-2*无意义时间的金钱数，奖励自己买礼物。）\u003c/p>\u003cp>学习者A:\u003c/p>\u003cp>1.我通过时间记录把我的时间分为5类：高效工作；陪孩子时间；被迫工作；休息；运动时间。\u003c/p>\u003cp>2.我的时间中，为实现去年马甲线的目标，花费时间为每周2h？需要调整为每天1h。\u003cbr>\u003c/p>\u003cp>3.制定规则奖励自己：运动时间连续超过1h并持续一周，就奖励休息一天。\u003c/p>\u003cp>学习者B:\u003c/p>\u003cp>1.我通过时间记录把我的时间分为3类：工作时间，休息时间，学习时间。\u003c/p>\u003cp>2.我的时间中，为实现去年一年100本书的目标，花费时间为每周0.5h？需要调整为每天1h。\u003cbr>\u003c/p>\u003cp>3.制定规则奖励自己：学习时间+工作时间-休息时间的分钟数折合成人民币给自己买礼物。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1472040859000,"updated_at":1472041010000,"ria":true},{"id":571,"topic":"甲之熊掌，乙之砒霜。","learn_goal":"顺利通过1-1","remark":"你是否认为一直以来，你在为对方不断地付出，但是对方却不理解你？你因此而心中感觉到苦闷，充满疑虑？你或许还在一度怀疑别人不理解你是别人的问题？那这次让我们来一起思考一下:你所给予的，是否是别人所需要的？\r\n","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"陈庆","city":"西安"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫陈庆。你们可以叫我大庆或者是大庆庆。平时的我喜欢听古典音乐，因为每当我听到古典音乐的时候我得内心就非常的愉悦。那时我就可以更好的与自己对话，也可以更好的了解我自.己。我还喜欢跑步，因为跑步可以给我带来一个健康的身体，还可以将生活的忧愁变为汗水蒸发掉。那我还爱笑，因为我相信:爱笑的人运气自然也不会太差，而且只要笑一笑，没有什么事情过不了~也是我人生的格言。我就是这样一个爱笑，爱跑步，爱听古典音乐的女孩~","ratings_count":0,"texts":[{"id":1584,"quote":"半年后，工作渐渐上了轨道，和家人沟通的时间越来越少。每天都在不停的讲课，下班还要备课，等到有一点属于自己的时间了，却已经累得没有讲话的力气，给妹妹和妈妈打电话的次数越来越少。有一次妈妈跟我打电话时都快哭出来了。她埋怨我说:\"你到底是怎样想的，你还要这个家吗？\"\r\n 我当时听了很委屈，辩解到:\"我这么拼搏为了什么？还不是为了你们？我做这些是为了让你们过得更好，为什么不理解我呢？\"\r\n 为什么不理解我呢？很多成年人都会有这样的疑问。答案很简单，你能有给予对方真正想要的。\r\n 那一次谈话让我意识到:即使你拼命而为，但在别人看来，你没有分享时间和感情，没有给予对方真正想要的东西，那就是你的错。甲之熊掌，乙之砒霜。你所给予的，未必是对方真正看中的。","explains":"你在为对方不断的努力，你想通过努力，给予她们更好的生活，更好的东西。所以一直以来，你都在付出着，在给予着。然而你的给予换来的是对方的不满和埋怨。对方的不理解，给我们带来一系列的疑问:“我这么努力为了什么？你为什么不理解我？”等等。我们都在付出，可是为什么我们带来的不是快乐，而是埋怨呢？给予的出发点可能是因为爱，也可能是因为为对方着想。这都没有错。造成相互不理解的原因是因为我们所给予的与对方所需要的不想匹配。所以在以后我们的生活当中，当我们去给予对方时，我们要思考以下几点:第一，别人需要什么？第二，我们应该用怎样正确的方式去给予别人？","interaction":"激活经验:2016年6月20日晚，也就是英语四级考完后的第一天。我后面的两个同学在记四级的单词。她们说他们没考好，再做准备。我当时想我四级过了，我跟她们分享一下方法。我给了一下两点分享:1.作文很重要，因为我在参加四级培训班时候，老师说以前有一位培训的学生，每周写好几篇作文，最后英语考了500多，当中作文就100左右。2.关键词很重要:四级单词量大，对于信息匹配题来说更是如此，找准关键词，再做题，就相对而言简单了。她们听了我得分享，她们说，我们连单词都不认识，给我们交方法，也没有用。于是我跟她们的分享就不欢而散了。事后我想了想，我分享的出发点没错，那为什么她们不接受呢？后来明白了:她们需要的是单词如何记，我提供的是做题方法。\r\n催化作用:1.给打工的弟弟打电话，给予他关爱，了解他的需求，适度的给予他。\r\n 2.下次再跟别人做分享时，先了解别人需要什么？需要哪些方面的分享？再去做进一步分享。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1467605646000,"updated_at":1467606538000,"ria":true}]};